/**
 * Validates whether an amount string is a non-negative decimal string with at most 2 decimal places.
 * Disallows: negative numbers, empty string, scientific notation, NaN, more than 2 decimal places.
 * Allowed formats: "0", "0.0", "0.00", "10", "10.5", "10.50", "199.90", etc.
 * Leading zeros? Usually "0", "0.1", "123". Regex: ^(0|[1-9]\d*)(\.\d{1,2})?$
 */
export function isValidAmount(value) {
	if (typeof value !== "string") return false;
	if (!/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(value)) return false;
	return true;
}

/**
 * Converts a valid amount string or integer to cents safely using integer arithmetic.
 */
export function toCents(value) {
	if (typeof value === "number") {
		return Math.round(value);
	}
	if (typeof value !== "string" || !isValidAmount(value)) {
		throw new Error(`Invalid amount format: ${value}`);
	}
	const [whole, frac = ""] = value.split(".");
	const centsFrac = (frac + "00").slice(0, 2);
	return Number(whole) * 100 + Number(centsFrac);
}

export function formatMoney(cents) {
	const sign = cents < 0 ? "-" : "";
	const abs = Math.abs(cents);
	const dollars = Math.floor(abs / 100);
	const fraction = (abs % 100).toString().padStart(2, "0");
	return `${sign}${dollars}.${fraction}`;
}

import { isValidAmount, toCents } from "./money.mjs";

const TIMEZONE = "Asia/Shanghai";
const MS_PER_HOUR = 3600 * 1000;
const OFFSET_8_HOURS = 8 * MS_PER_HOUR;

/**
 * Returns Beijing calendar date "YYYY-MM-DD" for an ISO date string or Date object.
 */
function getBeijingDateStr(isoString) {
	const ms = new Date(isoString).getTime();
	if (isNaN(ms)) return null;
	const beijingDate = new Date(ms + OFFSET_8_HOURS);
	const year = beijingDate.getUTCFullYear();
	const month = String(beijingDate.getUTCMonth() + 1).padStart(2, "0");
	const day = String(beijingDate.getUTCDate()).padStart(2, "0");
	return `${year}-${month}-${day}`;
}

export function reconcile(orders, events, { date, feeBps = 0 }) {
	const feeRate = Number(feeBps) || 0;

	// Calculate Beijing time boundary for the target date
	// Beijing date 'YYYY-MM-DD 00:00:00.000' is (UTC date - 8 hours)
	const [y, m, d] = date.split("-").map(Number);
	const startOfDayMs = Date.UTC(y, m - 1, d, 0, 0, 0, 0) - OFFSET_8_HOURS;
	const endOfDayMs = Date.UTC(y, m - 1, d, 23, 59, 59, 999) - OFFSET_8_HOURS;

	// 1. Filter orders created on target date (Beijing time)
	// Build order map for all orders to determine orphan vs outsideOrderDate
	const allOrderMap = new Map();
	for (const o of orders) {
		allOrderMap.set(o.id, o);
	}

	const targetOrders = orders.filter((o) => {
		const orderDate = getBeijingDateStr(o.createdAt);
		return orderDate === date;
	});

	// Sort target orders by ID ascending
	targetOrders.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

	const targetOrderMap = new Map();
	for (const o of targetOrders) {
		targetOrderMap.set(o.id, o);
	}

	// 2. Event deduplication and conflict check
	// Group events by eventId
	const eventsByEventId = new Map();
	for (const evt of events) {
		if (!eventsByEventId.has(evt.eventId)) {
			eventsByEventId.set(evt.eventId, []);
		}
		eventsByEventId.get(evt.eventId).push(evt);
	}

	const issues = [];
	const ignored = {
		duplicates: 0,
		notSucceeded: 0,
		afterCutoff: 0,
		outsideOrderDate: 0,
	};

	const deduplicatedEvents = [];

	for (const [eventId, group] of eventsByEventId.entries()) {
		if (group.length === 1) {
			deduplicatedEvents.push(group[0]);
		} else {
			// Compare orderId, amount, kind, state, occurredAt
			const first = group[0];
			let hasConflict = false;
			for (let i = 1; i < group.length; i++) {
				const item = group[i];
				if (
					item.orderId !== first.orderId ||
					item.amount !== first.amount ||
					item.kind !== first.kind ||
					item.state !== first.state ||
					item.occurredAt !== first.occurredAt
				) {
					hasConflict = true;
					break;
				}
			}

			if (hasConflict) {
				// Isolate entire ID before filtering status and date
				issues.push({
					eventId,
					orderId: first.orderId,
					code: "conflicting_duplicate",
				});
			} else {
				// Exact duplicate: keep one, and increment duplicates count for each redundant copy
				ignored.duplicates += group.length - 1;
				deduplicatedEvents.push(first);
			}
		}
	}

	// Order-level aggregates
	const orderPayments = new Map();
	const orderRefunds = new Map();
	const orderFees = new Map();

	for (const o of targetOrders) {
		orderPayments.set(o.id, 0);
		orderRefunds.set(o.id, 0);
		orderFees.set(o.id, 0);
	}

	// Process deduplicated events in evaluation order:
	// 1. state !== succeeded -> notSucceeded++
	// 2. occurredAt > endOfDayMs -> afterCutoff++
	// 3. !allOrderMap.has(orderId) -> orphan_event issue
	// 4. !targetOrderMap.has(orderId) -> outsideOrderDate++
	// 5. !isValidAmount(amount) -> invalid_amount issue
	// 6. valid event: accumulate
	for (const evt of deduplicatedEvents) {
		if (evt.state !== "succeeded") {
			ignored.notSucceeded++;
			continue;
		}

		const occurredMs = new Date(evt.occurredAt).getTime();
		if (occurredMs > endOfDayMs) {
			ignored.afterCutoff++;
			continue;
		}

		if (!allOrderMap.has(evt.orderId)) {
			issues.push({
				eventId: evt.eventId,
				orderId: evt.orderId,
				code: "orphan_event",
			});
			continue;
		}

		if (!targetOrderMap.has(evt.orderId)) {
			ignored.outsideOrderDate++;
			continue;
		}

		if (!isValidAmount(evt.amount)) {
			issues.push({
				eventId: evt.eventId,
				orderId: evt.orderId,
				code: "invalid_amount",
			});
			continue;
		}

		const amountCents = toCents(evt.amount);
		if (evt.kind === "payment") {
			orderPayments.set(evt.orderId, orderPayments.get(evt.orderId) + amountCents);
			if (feeRate > 0) {
				const fee = Math.round((amountCents * feeRate) / 10000);
				orderFees.set(evt.orderId, orderFees.get(evt.orderId) + fee);
			}
		} else if (evt.kind === "refund") {
			orderRefunds.set(evt.orderId, orderRefunds.get(evt.orderId) + amountCents);
		}
	}

	// Build orders report
	const orderRows = targetOrders.map((order) => {
		const amountCents = isValidAmount(order.amount) ? toCents(order.amount) : 0;
		const paymentCents = orderPayments.get(order.id) || 0;
		const refundCents = orderRefunds.get(order.id) || 0;
		const netCents = paymentCents - refundCents;
		const outstandingCents = Math.max(amountCents - paymentCents, 0);
		const overpaidCents = Math.max(paymentCents - amountCents, 0);

		let status = "unpaid";
		if (refundCents > 0) {
			status = "refunded";
		} else if (paymentCents === 0) {
			status = "unpaid";
		} else if (paymentCents < amountCents) {
			status = "partial";
		} else if (paymentCents > amountCents) {
			status = "overpaid";
		} else {
			status = "paid";
		}

		const feeCents = orderFees.get(order.id) || 0;
		const settlementCents = netCents - feeCents;

		const row = {
			id: order.id,
			amountCents,
			paymentCents,
			refundCents,
			netCents,
			outstandingCents,
			overpaidCents,
			status,
		};

		if (feeBps !== undefined) {
			row.feeCents = feeCents;
			row.settlementCents = settlementCents;
		}

		return row;
	});

	const totals = {
		orderCount: orderRows.length,
		orderCents: orderRows.reduce((sum, r) => sum + r.amountCents, 0),
		paymentCents: orderRows.reduce((sum, r) => sum + r.paymentCents, 0),
		refundCents: orderRows.reduce((sum, r) => sum + r.refundCents, 0),
		netCents: orderRows.reduce((sum, r) => sum + r.netCents, 0),
		outstandingCents: orderRows.reduce((sum, r) => sum + r.outstandingCents, 0),
		overpaidCents: orderRows.reduce((sum, r) => sum + r.overpaidCents, 0),
	};

	if (feeBps !== undefined) {
		totals.feeCents = orderRows.reduce((sum, r) => sum + r.feeCents, 0);
		totals.settlementCents = orderRows.reduce((sum, r) => sum + r.settlementCents, 0);
	}

	return {
		date,
		timezone: TIMEZONE,
		totals,
		orders: orderRows,
		ignored,
		issues,
	};
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { formatMoney } from "./money.mjs";
import { reconcile } from "./reconcile.mjs";

const args = process.argv.slice(2);
const options = {};
for (let i = 0; i < args.length; i += 2) {
	const key = args[i].replace(/^--/, "");
	options[key] = args[i + 1];
}

const orders = JSON.parse(readFileSync(options.orders, "utf8"));
const events = JSON.parse(readFileSync(options.events, "utf8"));

const reconcileOptions = {
	date: options.date,
};
if (options["fee-bps"] !== undefined) {
	reconcileOptions.feeBps = Number(options["fee-bps"]);
}

const report = reconcile(orders, events, reconcileOptions);
mkdirSync(options.out, { recursive: true });
writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);

const hasFee = options["fee-bps"] !== undefined;
const header = ["order_id", "amount", "payment", "refund", "net", "status", "outstanding", "overpaid"];
if (hasFee) {
	header.push("fee", "settlement");
}

const csv = [header.join(",")];
for (const row of report.orders) {
	const line = [
		row.id,
		formatMoney(row.amountCents),
		formatMoney(row.paymentCents),
		formatMoney(row.refundCents),
		formatMoney(row.netCents),
		row.status,
		formatMoney(row.outstandingCents),
		formatMoney(row.overpaidCents),
	];
	if (hasFee) {
		line.push(formatMoney(row.feeCents), formatMoney(row.settlementCents));
	}
	csv.push(line.join(","));
}
writeFileSync(join(options.out, `${options.date}.csv`), `${csv.join("\n")}\n`);
console.log(JSON.stringify({ json: `${options.out}/${options.date}.json`, csv: `${options.out}/${options.date}.csv` }));

import assert from \"node:assert/strict\";
import test from \"node:test\";
import { formatMoney, isValidAmount, toCents } from \"../src/money.mjs\";
import { reconcile } from \"../src/reconcile.mjs\";

test(\"money: isValidAmount rejects invalid amounts and accepts valid ones\", () => {
	assert.equal(isValidAmount(\"10.00\"), true);
	assert.equal(isValidAmount(\"0\"), true);
	assert.equal(isValidAmount(\"0.30\"), true);
	assert.equal(isValidAmount(\"-5.00\"), false);
	assert.equal(isValidAmount(\"1e5\"), false);
	assert.equal(isValidAmount(\"NaN\"), false);
	assert.equal(isValidAmount(\"\"), false);
	assert.equal(isValidAmount(\"10.999\"), false);
});

test(\"money: toCents handles decimal precision safely\", () => {
	assert.equal(toCents(\"199.90\"), 19990);
	assert.equal(toCents(\"0.10\") + toCents(\"0.20\"), 30);
	assert.equal(toCents(\"4.10\"), 410);
	assert.equal(formatMoney(30), \"0.30\");
	assert.equal(formatMoney(19990), \"199.90\");
});

test(\"reconcile: one simple payment\", () => {
	const report = reconcile(
		[{ id: \"demo\", amount: \"10.00\", createdAt: \"2026-10-20T01:00:00Z\" }],
		[{ eventId: \"demo-pay\", orderId: \"demo\", kind: \"payment\", state: \"succeeded\", amount: \"10.00\", occurredAt: \"2026-10-20T02:00:00Z\" }],
		{ date: \"2026-10-20\" },
	);
	assert.equal(report.totals.netCents, 1000);
	assert.equal(report.orders[0].status, \"paid\");
});

test(\"reconcile: beijing timezone boundaries and cutoff\", () => {
	const orders = [
		// 2026-10-19 15:59:59Z is 2026-10-19 23:59:59 Beijing time (previous day)
		{ id: \"O_PREV\", amount: \"10.00\", createdAt: \"2026-10-19T15:59:59Z\" },
		// 2026-10-19 16:00:00Z is 2026-10-20 00:00:00 Beijing time (start of day)
		{ id: \"O_START\", amount: \"20.00\", createdAt: \"2026-10-19T16:00:00Z\" },
		// 2026-10-20 15:59:59.999Z is 2026-10-20 23:59:59.999 Beijing time (end of day)
		{ id: \"O_END\", amount: \"30.00\", createdAt: \"2026-10-20T15:59:59.999Z\" },
		// 2026-10-20 16:00:00Z is 2026-10-21 00:00:00 Beijing time (next day)
		{ id: \"O_NEXT\", amount: \"40.00\", createdAt: \"2026-10-20T16:00:00Z\" },
	];

	const events = [
		{ eventId: \"e1\", orderId: \"O_START\", kind: \"payment\", state: \"succeeded\", amount: \"20.00\", occurredAt: \"2026-10-19T16:00:00Z\" },
		// Occurred at 2026-10-20 16:00:01Z -> Beijing 2026-10-21 00:00:01 (after cutoff)
		{ eventId: \"e2\", orderId: \"O_END\", kind: \"payment\", state: \"succeeded\", amount: \"30.00\", occurredAt: \"2026-10-20T16:00:01Z\" },
	];

	const report = reconcile(orders, events, { date: \"2026-10-20\" });
	assert.deepEqual(report.orders.map((o) => o.id), [\"O_END\", \"O_START\"]);
	assert.equal(report.ignored.afterCutoff, 1);
	assert.equal(report.orders.find((o) => o.id === \"O_START\").paymentCents, 2000);
	assert.equal(report.orders.find((o) => o.id === \"O_END\").paymentCents, 0);
});

test(\"reconcile: duplicates, orphans, invalid amounts, and status categorization\", () => {
	const orders = [
		{ id: \"O1\", amount: \"100.00\", createdAt: \"2026-10-20T01:00:00Z\" },
		{ id: \"O2\", amount: \"50.00\", createdAt: \"2026-10-20T02:00:00Z\" },
		{ id: \"O3\", amount: \"40.00\", createdAt: \"2026-10-20T03:00:00Z\" },
	];

	const events = [
		// Exact duplicate: should be counted once in payment and ignored.duplicates = 1
		{ eventId: \"dup1\", orderId: \"O1\", kind: \"payment\", state: \"succeeded\", amount: \"60.00\", occurredAt: \"2026-10-20T04:00:00Z\" },
		{ eventId: \"dup1\", orderId: \"O1\", kind: \"payment\", state: \"succeeded\", amount: \"60.00\", occurredAt: \"2026-10-20T04:00:00Z\" },
		// Refund on O1
		{ eventId: \"ref1\", orderId: \"O1\", kind: \"refund\", state: \"succeeded\", amount: \"10.00\", occurredAt: \"2026-10-20T05:00:00Z\" },
		// Overpayment on O2
		{ eventId: \"pay2\", orderId: \"O2\", kind: \"payment\", state: \"succeeded\", amount: \"70.00\", occurredAt: \"2026-10-20T06:00:00Z\" },
		// Orphan event
		{ eventId: \"orphan\", orderId: \"O999\", kind: \"payment\", state: \"succeeded\", amount: \"10.00\", occurredAt: \"2026-10-20T07:00:00Z\" },
		// Invalid amount
		{ eventId: \"inv\", orderId: \"O3\", kind: \"payment\", state: \"succeeded\", amount: \"-10.00\", occurredAt: \"2026-10-20T08:00:00Z\" },
		// Non-succeeded
		{ eventId: \"fail\", orderId: \"O3\", kind: \"payment\", state: \"failed\", amount: \"40.00\", occurredAt: \"2026-10-20T09:00:00Z\" },
	];

	const report = reconcile(orders, events, { date: \"2026-10-20\" });
	assert.equal(report.ignored.duplicates, 1);
	assert.equal(report.ignored.notSucceeded, 1);
	assert.deepEqual(report.issues.map((i) => `${i.eventId}:${i.code}`), [
		\"orphan:orphan_event\",
		\"inv:invalid_amount\",
	]);

	const o1 = report.orders.find((o) => o.id === \"O1\");
	assert.equal(o1.status, \"refunded\");
	assert.equal(o1.paymentCents, 6000);
	assert.equal(o1.refundCents, 1000);
	assert.equal(o1.outstandingCents, 4000); // 100 - 60 = 40 (refund does not create extra outstanding)

	const o2 = report.orders.find((o) => o.id === \"O2\");
	assert.equal(o2.status, \"overpaid\");
	assert.equal(o2.overpaidCents, 2000);

	const o3 = report.orders.find((o) => o.id === \"O3\");
	assert.equal(o3.status, \"unpaid\");
	assert.equal(o3.outstandingCents, 4000);
});

test(\"reconcile: conflicting duplicates and fee calculations\", () => {
	const orders = [
		{ id: \"O1\", amount: \"100.00\", createdAt: \"2026-10-20T01:00:00Z\" },
	];

	const events = [
		{ eventId: \"c1\", orderId: \"O1\", kind: \"payment\", state: \"succeeded\", amount: \"50.00\", occurredAt: \"2026-10-20T02:00:00Z\" },
		{ eventId: \"c1\", orderId: \"O1\", kind: \"payment\", state: \"succeeded\", amount: \"60.00\", occurredAt: \"2026-10-20T02:00:00Z\" },
		{ eventId: \"valid\", orderId: \"O1\", kind: \"payment\", state: \"succeeded\", amount: \"40.00\", occurredAt: \"2026-10-20T03:00:00Z\" },
	];

	const report = reconcile(orders, events, { date: \"2026-10-20\", feeBps: 60 });
	assert.equal(report.issues[0].code, \"conflicting_duplicate\");
	// c1 is quarantined, only valid (40.00) is counted
	const o1 = report.orders[0];
	assert.equal(o1.paymentCents, 4000);
	// fee: 4000 * 60 / 10000 = 24 cents
	assert.equal(o1.feeCents, 24);
	assert.equal(o1.settlementCents, 4000 - 24);
});

