		{ date: "2026-10-20" },
	);
	assert.equal(report.totals.netCents, 1000);
	assert.equal(report.orders[0].status, "paid");
});

test("reconcile: beijing timezone boundaries and cutoff", () => {
	const orders = [
		{ id: "O_PREV", amount: "10.00", createdAt: "2026-10-19T15:59:59Z" },
		{ id: "O_START", amount: "20.00", createdAt: "2026-10-19T16:00:00Z" },
		{ id: "O_END", amount: "30.00", createdAt: "2026-10-20T15:59:59.999Z" },
		{ id: "O_NEXT", amount: "40.00", createdAt: "2026-10-20T16:00:00Z" },
	];

	const events = [
		{ eventId: "e1", orderId: "O_START", kind: "payment", state: "succeeded", amount: "20.00", occurredAt: "2026-10-19T16:00:00Z" },
		{ eventId: "e2", orderId: "O_END", kind: "payment", state: "succeeded", amount: "30.00", occurredAt: "2026-10-20T16:00:01Z" },
	];

	const report = reconcile(orders, events, { date: "2026-10-20" });
	assert.deepEqual(report.orders.map((o) => o.id), ["O_END", "O_START"]);
	assert.equal(report.ignored.afterCutoff, 1);
	assert.equal(report.orders.find((o) => o.id === "O_START").paymentCents, 2000);
	assert.equal(report.orders.find((o) => o.id === "O_END").paymentCents, 0);
