import { join } from "node:path";
import { reconcile } from "../src/reconcile.mjs";
import { toCents, formatMoney } from "../src/money.mjs";
import { main } from "../src/cli.mjs";

const date = "2026-10-20";
const order = (id = "a", amount = "10.00", createdAt = "2026-10-20T00:00:00+08:00") => ({ id, amount, createdAt });
const event = (eventId, changes = {}) => ({ eventId, orderId: "a", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T01:00:00+08:00", ...changes });
const run = (orders, events) => reconcile(orders, events, { date });
const load = name => JSON.parse(readFileSync(new URL(`../data/${name}.json`, import.meta.url), "utf8"));

test("money uses exact integer cents and strict decimal strings", () => {
	assert.equal(toCents("0.10") + toCents("0.20"), 30);
	assert.equal(toCents("1.13"), 113);
	assert.equal(toCents("0"), 0);
	assert.equal(toCents("12.3"), 1230);
	for (const invalid of ["-5.00", "", " ", "1e2", "NaN", "Infinity", "1.001", "1.", ".1", "+1", " 1", 1, null, "90071992547409.92"]) assert.throws(() => toCents(invalid));
	assert.equal(formatMoney(-1), "-0.01");
	assert.equal(formatMoney(0), "0.00");
	assert.equal(formatMoney(Number.MAX_SAFE_INTEGER), "90071992547409.91");
});

test("Beijing creation boundaries, cutoff milliseconds and occurredAt not receivedAt", () => {
	const orders = [order("before", "10", "2026-10-19T15:59:59.999Z"), order("start", "10", "2026-10-19T16:00:00Z"), order("last", "10", "2026-10-20T15:59:59.999Z"), order("next", "10", "2026-10-20T16:00:00Z")];
	const r = run(orders, [event("ok", { orderId: "start", occurredAt: "2026-10-20T15:59:59.999Z", receivedAt: "2026-10-21T00:00:00Z" }), event("late", { orderId: "last", occurredAt: "2026-10-20T16:00:00Z" }), event("other", { orderId: "before" })]);
	assert.deepEqual(r.orders.map(r => r.id), ["last", "start"]);
	assert.equal(r.totals.paymentCents, 1000);
	assert.equal(r.ignored.afterCutoff, 1);
	assert.equal(r.ignored.outsideOrderDate, 1);
	assert.deepEqual(r.issues, []);
});

test("duplicates, states, cutoff, orphan, outside day, invalid amount follow priority", () => {
	const failed = event("failed", { state: "failed", orderId: "missing", amount: "bad", occurredAt: "2026-10-21T00:00:00Z" });
	const r = run([order(), order("old", "10", "2026-10-18T00:00:00Z")], [event("ok"), event("ok"), failed, failed, event("pending", { state: "pending" }), event("late", { orderId: "missing", occurredAt: "2026-10-21T00:00:00Z" }), event("orphan", { orderId: "missing", amount: "bad" }), event("outside", { orderId: "old", amount: "bad" }), event("invalid", { amount: "-1" }), event("unknown", { kind: "adjustment" })]);
	assert.equal(r.totals.paymentCents, 1000);
	assert.deepEqual(r.ignored, { duplicates: 2, notSucceeded: 3, afterCutoff: 1, outsideOrderDate: 1 });
	assert.deepEqual(r.issues, [{ eventId: "orphan", orderId: "missing", code: "orphan_event" }, { eventId: "invalid", orderId: "a", code: "invalid_amount" }]);
});

test("statuses and refund do not recreate debt; payments and refunds deduplicate", () => {
	const pay = event("p", { orderId: "refunded" });
	const refund = event("r", { orderId: "refunded", kind: "refund", amount: "4" });
	const r = run(["unpaid", "partial", "paid", "overpaid", "refunded"].map(id => order(id)), [event("part", { orderId: "partial", amount: "3" }), event("full", { orderId: "paid" }), event("over", { orderId: "overpaid", amount: "12" }), pay, pay, refund, refund]);
	const rows = Object.fromEntries(r.orders.map(row => [row.id, row]));
	for (const status of ["unpaid", "partial", "paid", "overpaid", "refunded"]) assert.equal(rows[status].status, status);
	assert.equal(rows.refunded.netCents, 600);
	assert.equal(rows.refunded.outstandingCents, 0);
	assert.equal(rows.partial.outstandingCents, 700);
	assert.equal(rows.overpaid.overpaidCents, 200);
	assert.equal(r.ignored.duplicates, 2);
});

test("actual input regression: every row, total, ignore and issue", () => {
	const r = run(load("orders"), load("events"));
	assert.equal(r.timezone, "Asia/Shanghai");
	assert.deepEqual(r.totals, { orderCount: 7, orderCents: 55520, paymentCents: 43020, refundCents: 2000, netCents: 41020, outstandingCents: 15500, overpaidCents: 3000 });
	assert.deepEqual(r.orders.map(r => [r.id, r.paymentCents, r.refundCents, r.outstandingCents, r.overpaidCents, r.status]), [
		["O1001", 19990, 0, 0, 0, "paid"], ["O1002", 3000, 0, 5000, 0, "partial"], ["O1003", 5000, 2000, 0, 0, "refunded"], ["O1004", 15000, 0, 0, 3000, "overpaid"], ["O1005", 0, 0, 3500, 0, "unpaid"], ["O1006", 30, 0, 0, 0, "paid"], ["O1007", 0, 0, 7000, 0, "unpaid"],
	]);
	assert.deepEqual(r.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 2, outsideOrderDate: 0 });
	assert.deepEqual(r.issues, [{ eventId: "e09", orderId: "O9999", code: "orphan_event" }, { eventId: "e13", orderId: "O1005", code: "invalid_amount" }]);
