import { toCents, addCents } from "./money.mjs";

function timestamp(value) {
	if (typeof value !== "string" || !/(Z|[+-]\d{2}:\d{2})$/.test(value)) throw new TypeError("时间必须明确包含时区");
	const time = Date.parse(value);
	if (!Number.isFinite(time)) throw new TypeError("非法时间");
	return time;
}

export function reconcile(orders, events, { date }) {
	if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || new Date(`${date}T00:00:00Z`).toISOString().slice(0, 10) !== date) throw new TypeError("非法日期");
	const start = timestamp(`${date}T00:00:00+08:00`);
	const end = start + 86400000;
	const allOrders = new Map();
	const selected = new Map();
	for (const order of orders) {
		if (allOrders.has(order.id)) throw new TypeError(`订单 ID 重复: ${order.id}`);
		allOrders.set(order.id, order);
		const created = timestamp(order.createdAt);
		if (created >= start && created < end) selected.set(order.id, {
			id: order.id, amountCents: toCents(order.amount), paymentCents: 0, refundCents: 0,
		});
	}
	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seen = new Set();
	for (const event of events) {
		if (seen.has(event.eventId)) { ignored.duplicates++; continue; }
		seen.add(event.eventId);
		if (event.state !== "succeeded" || !["payment", "refund"].includes(event.kind)) { ignored.notSucceeded++; continue; }
		if (timestamp(event.occurredAt) >= end) { ignored.afterCutoff++; continue; }
		const issue = (code) => issues.push({ eventId: event.eventId, orderId: event.orderId, code });
		if (!allOrders.has(event.orderId)) { issue("orphan_event"); continue; }
		if (!selected.has(event.orderId)) { ignored.outsideOrderDate++; continue; }
		let cents;
		try { cents = toCents(event.amount); } catch { issue("invalid_amount"); continue; }
		const row = selected.get(event.orderId);
		const key = event.kind === "payment" ? "paymentCents" : "refundCents";
		row[key] = addCents(row[key], cents);
	}
	const rows = [...selected.values()].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
	for (const row of rows) {
		row.netCents = row.paymentCents - row.refundCents;
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
		row.status = row.refundCents > 0 ? "refunded" : row.paymentCents === 0 ? "unpaid" : row.outstandingCents > 0 ? "partial" : row.overpaidCents > 0 ? "overpaid" : "paid";
	}
	const totals = { orderCount: rows.length };
	for (const key of ["amountCents", "paymentCents", "refundCents", "netCents", "outstandingCents", "overpaidCents"]) {
		totals[key === "amountCents" ? "orderCents" : key] = rows.reduce((sum, row) => addCents(sum, row[key]), 0);
	}
	return { date, timezone: "Asia/Shanghai", totals, orders: rows, ignored, issues };
}

import { formatMoney as money } from "./money.mjs";

export function renderSummary(report) {
	const t = report.totals;
	const lines = [
		`# ${report.date} 日结对账交接`, "",
		"口径：北京时间当天创建的订单，截至当天 23:59:59.999 已发生的成功支付和成功退款，按 occurredAt 而非 receivedAt 判断。金额内部按整数分计算，下文单位为元。", "",
		`共 ${t.orderCount} 个订单，应收 ${money(t.orderCents)}；收款 **${money(t.paymentCents)}**，退款 **${money(t.refundCents)}**，净收款 **${money(t.netCents)}**。`,
		`原订单未收齐合计 ${money(t.outstandingCents)}；多付款合计 ${money(t.overpaidCents)}。`, "",
		"## 待催款 / 核实未收款", "",
	];
	const outstanding = report.orders.filter(r => r.outstandingCents > 0);
	lines.push(...(outstanding.length ? outstanding.map(r => `- ${r.id}：订单 ${money(r.amountCents)}，已收 ${money(r.paymentCents)}，未收齐 ${money(r.outstandingCents)}。`) : ["- 无。"]));
	lines.push("", "## 多付款处理", "");
	const overpaid = report.orders.filter(r => r.overpaidCents > 0);
	lines.push(...(overpaid.length ? overpaid.map(r => `- ${r.id}：已收 ${money(r.paymentCents)}，订单 ${money(r.amountCents)}，多付款 ${money(r.overpaidCents)}，请核实后处理，脚本不会自动退款。`) : ["- 无。"]));
	lines.push("", "## 已退款（不重新记作欠款）", "");
	const refunded = report.orders.filter(r => r.refundCents > 0);
	lines.push(...(refunded.length ? refunded.map(r => `- ${r.id}：已收 ${money(r.paymentCents)}，已退 ${money(r.refundCents)}，净收 ${money(r.netCents)}，原订单未收齐 ${money(r.outstandingCents)}。`) : ["- 无。"]));
	lines.push("", "## 人工核查（均未计入财务合计）", "");
	lines.push(...(report.issues.length ? report.issues.map(i => `- ${i.eventId} / ${i.orderId}：${i.code === "orphan_event" ? "找不到订单，请核对订单归属及渠道账单" : "金额不合法，请核对原始通知及渠道账单"}（${i.code}）。`) : ["- 无。"]));
	lines.push("", "## 检查与限制", "",
		`- 已按顺序检查：重复通知、成功状态、截止时间、订单存在性、订单创建日、金额合法性。忽略普通重复 ${report.ignored.duplicates} 条、非成功/不支持类型 ${report.ignored.notSucceeded} 条、截止后 ${report.ignored.afterCutoff} 条、其他日期订单 ${report.ignored.outsideOrderDate} 条。`,
		"- JSON 金额为整数分；CSV 金额为两位小数元。收款减退款等于净收款；退款不增加原订单欠款。",
		"- 本次为第一轮文件核算；未使用 events-update.json 或第二轮手续费规则。报表不是银行到账确认，未收款、多付款和异常须人工确认后操作。未来成功通知可能改变后续报表。",
		"- 输入要求订单 ID 唯一、时间有效且含时区；非法订单金额、非法时间或合计超出安全整数范围会报错，避免静默生成不可信结果。", "");
	return lines.join("\n");
}

