export function validateFeeBps(feeBps) {
	if (!Number.isSafeInteger(feeBps) || feeBps < 0) throw new TypeError("fee-bps 必须是非负安全整数（万分比）");
	return feeBps;
}

export function paymentFee(cents, feeBps) {
	validateFeeBps(feeBps);
	if (!Number.isSafeInteger(cents) || cents < 0) throw new TypeError("手续费本金必须是非负安全整数分");
	// 非负数四舍五入；全程整数运算，不先做浮点乘法。
	const fee = (BigInt(cents) * BigInt(feeBps) + 5000n) / 10000n;
	if (fee > BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError("手续费超出安全整数范围");
	return Number(fee);
}

