import { toCents, addCents } from "./money.mjs";
import { paymentFee, validateFeeBps } from "./fees.mjs";

function timestamp(value) {
	if (typeof value !== "string" || !/(Z|[+-]\d{2}:\d{2})$/.test(value)) throw new TypeError("时间必须明确包含时区");
	const time = Date.parse(value);
	if (!Number.isFinite(time)) throw new TypeError("非法时间");
	return time;
}

const conflictFields = ["orderId", "amount", "kind", "state", "occurredAt"];
function groupEvents(events) {
	const groups = new Map();
	for (const event of events) {
		const group = groups.get(event.eventId);
		if (!group) groups.set(event.eventId, { first: event, count: 1, conflict: false });
		else {
			group.count++;
			if (conflictFields.some(key => event[key] !== group.first[key])) group.conflict = true;
		}
	}
	return groups;
}

export function reconcile(orders, events, { date, feeBps = 0 }) {
	validateFeeBps(feeBps);
	if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || new Date(`${date}T00:00:00Z`).toISOString().slice(0, 10) !== date) throw new TypeError("非法日期");
