import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync, mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";
import { reconcile } from "../src/reconcile.mjs";
import { toCents, formatMoney } from "../src/money.mjs";
import { main } from "../src/cli.mjs";

const date = "2026-10-20";
const order = (id = "a", amount = "10.00", createdAt = "2026-10-20T00:00:00+08:00") => ({ id, amount, createdAt });
const event = (eventId, changes = {}) => ({ eventId, orderId: "a", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T01:00:00+08:00", ...changes });
const run = (orders, events) => reconcile(orders, events, { date });
const load = name => JSON.parse(readFileSync(new URL(`../data/${name}.json`, import.meta.url), "utf8"));

test("money: exact cents, strict decimal strings, safe range and formatting", () => {
	assert.equal(toCents("0.10") + toCents("0.20"), 30);
	assert.equal(toCents("1.13"), 113);
	assert.equal(toCents("0"), 0);
	assert.equal(toCents("12.3"), 1230);
	for (const invalid of ["-5.00", "", " ", "1e2", "NaN", "Infinity", "1.001", "1.", ".1", "+1", " 1", 1, null, "90071992547409.92"]) assert.throws(() => toCents(invalid));
	assert.equal(formatMoney(-1), "-0.01");
	assert.equal(formatMoney(0), "0.00");
	assert.equal(formatMoney(Number.MAX_SAFE_INTEGER), "90071992547409.91");
});

test("Beijing creation boundaries, cutoff milliseconds and occurredAt not receivedAt", () => {
	const orders = [order("before", "10", "2026-10-19T15:59:59.999Z"), order("start", "10", "2026-10-19T16:00:00Z"), order("last", "10", "2026-10-20T15:59:59.999Z"), order("next", "10", "2026-10-20T16:00:00Z")];
	const r = run(orders, [event("ok", { orderId: "start", occurredAt: "2026-10-20T15:59:59.999Z", receivedAt: "2026-10-21T00:00:00Z" }), event("late", { orderId: "last", occurredAt: "2026-10-20T16:00:00Z" }), event("other", { orderId: "before" })]);
