export function renderSummary(report, { feeBps = 0, events = [], ordersPath = "", eventsPath = "" } = {}) {
	const t = report.totals;
	const lines = [
		`# ${report.date} 日结对账交接`, "",
		`输入：${ordersPath}；${eventsPath}。`,
		"口径：北京时间当天创建的订单，截至当天 23:59:59.999 已发生的成功支付和成功退款，按 occurredAt 而非 receivedAt 判断。文件收到时间不影响归属。金额内部按整数分计算，下文单位为元。", "",
		`共 ${t.orderCount} 个订单，应收 ${money(t.orderCents)}；收款 **${money(t.paymentCents)}**，退款 **${money(t.refundCents)}**，净收款 **${money(t.netCents)}**。`,
		`手续费率 ${feeBps} 万分比，逐笔成功有效支付四舍五入到分：手续费 **${money(t.feeCents)}**，预计到账 **${money(t.settlementCents)}**。退款不退还手续费；净收款不扣手续费。`,
		`原订单未收齐合计 ${money(t.outstandingCents)}；多付款合计 ${money(t.overpaidCents)}。`, "",
		"## 待催款 / 核实未收款", "",
	];
	const outstanding = report.orders.filter(r => r.outstandingCents > 0);
	lines.push(...(outstanding.length ? outstanding.map(r => `- ${r.id}：订单 ${money(r.amountCents)}，已收 ${money(r.paymentCents)}，未收齐 ${money(r.outstandingCents)}。催款前核对最新支付状态及异常。`) : ["- 无：本次有效成功支付已收齐全部原订单金额。"]));
	lines.push("", "## 多付款处理", "");
	const overpaid = report.orders.filter(r => r.overpaidCents > 0);
	lines.push(...(overpaid.length ? overpaid.map(r => `- ${r.id}：已收 ${money(r.paymentCents)}，订单 ${money(r.amountCents)}，多付款 ${money(r.overpaidCents)}，请核实后处理，脚本不会自动退款。`) : ["- 无有效入账记录形成的多付款；有冲突的通知仍须人工核查。"]));
	lines.push("", "## 已退款（不重新记作欠款）", "");
	const refunded = report.orders.filter(r => r.refundCents > 0);
	lines.push(...(refunded.length ? refunded.map(r => `- ${r.id}：已收 ${money(r.paymentCents)}，已退 ${money(r.refundCents)}，净收 ${money(r.netCents)}，手续费 ${money(r.feeCents)}，预计到账 ${money(r.settlementCents)}，原订单未收齐 ${money(r.outstandingCents)}。`) : ["- 无。"]));
	lines.push("", "## 人工核查（均未计入收款、退款或手续费）", "");
	const descriptions = {
		orphan_event: "找不到订单，请核对订单归属及渠道账单",
		invalid_amount: "金额不合法，请核对原始通知及渠道账单",
		conflicting_duplicate: "这组通知有矛盾，需要核对渠道账单；该 ID 的所有版本均已隔离，脚本不判断哪个版本为真",
	};
	lines.push(...(report.issues.length ? report.issues.map(i => {
		const versions = events.filter(e => e.eventId === i.eventId);
		const details = [...new Set(versions.map(e => `${e.orderId} / ${e.amount}`))].join("；");
		return `- ${i.eventId} / ${i.orderId}：${descriptions[i.code]}（${i.code}）。通知中的订单 / 金额：${details}。`;
	}) : ["- 无。"]));
	if (/(^|\/)events-update\.json$/.test(eventsPath)) {
		const originalOrders = JSON.parse(readFileSync(new URL("../data/orders.json", import.meta.url), "utf8"));
		const originalEvents = JSON.parse(readFileSync(new URL("../data/events.json", import.meta.url), "utf8"));
		const baseline = reconcile(originalOrders, originalEvents, { date: report.date }).totals;
		const delta = (key) => `${t[key] >= baseline[key] ? "+" : ""}${money(t[key] - baseline[key])}`;
		lines.push("", "## 与第一轮交付比较", "",
			"第一轮按 data/orders.json、data/events.json、零手续费口径重新计算作为基线；正号为增加，负号为减少。", "",
			"| 项目 | 第一轮 | 本轮 | 变化 |", "|---|---:|---:|---:|");
		for (const [label, key] of [["收款", "paymentCents"], ["退款", "refundCents"], ["净收款（未扣手续费）", "netCents"], ["手续费", "feeCents"], ["预计到账", "settlementCents"], ["未收齐", "outstandingCents"], ["多付款", "overpaidCents"]]) lines.push(`| ${label} | ${money(baseline[key])} | ${money(t[key])} | ${delta(key)} |`);
		lines.push("", "- e15、e17、e18 的发生时间均在本次截止前，虽次日收到，仍补计支付 50.00、35.00、70.00，合计 155.00。e16 同理补计退款 49.90。",
			"- e05 的 150.00 与 15.00 两个版本冲突，整组隔离：撤去第一轮计入的 150.00；不采用任何一版。e20 为独立通知，另计有效支付 120.00，不属于 e05 冲突组。",
			"- 因此收款净增加 155.00 - 150.00 + 120.00 = 125.00；退款增加 49.90，净收款增加 75.10。",
			`- 第一轮未计手续费（费率默认零），本轮按 ${feeBps} 万分比逐笔计费，手续费变化 ${delta("feeCents")}，预计到账变化 ${delta("settlementCents")}。此为两轮报表口径对比，不表示渠道第一轮实际没有收费。`,
			"- O1002、O1005、O1007 已按有效补单收齐；O1004 依独立 e20 收齐，但 e05 冲突尚未解决。e08 的次日付款仍不计入本次，需在后续日结核对，避免自动判断重复或多付。"
		);
	}
	lines.push("", "## 检查与限制", "",
		`- 先扫描所有 eventId 的五个业务字段冲突，再按普通重复、成功状态、截止时间、订单存在性、订单创建日、金额合法性处理。receivedAt 不参与冲突比较。忽略普通重复 ${report.ignored.duplicates} 条、非成功/不支持类型 ${report.ignored.notSucceeded} 条、截止后 ${report.ignored.afterCutoff} 条、其他日期订单 ${report.ignored.outsideOrderDate} 条；冲突组不记普通重复。`,
		"- 手续费仅对最终入账的成功支付逐笔收取，退款不产生手续费也不退手续费。JSON 金额为整数分；CSV 以元保留两位小数，保留原八列并追加 fee、settlement。",
		"- 金额、手续费计算及舍入用整数运算；不合法订单金额、无时区或非法时间、重复订单 ID、安全整数溢出会报错。",
		"- 报表根据文件核算，并非银行实际到账确认。冲突、孤儿及非法金额须人工核查；预计到账不包含未提供的其他渠道调整。脚本不自动催款、退款或操作真实业务系统。",
		"- 执行测试及独立验收结果见 reports/verification.md。", "");
	return lines.join("\n");
}

