export function toCents(value) {
	const text = String(value ?? "").trim();
	if (text === "" || !/^\d+(?:\.\d{1,2})?$/.test(text)) {
		throw new TypeError(`Invalid money amount: ${value}`);
	}
	const [whole, fraction = ""] = text.split(".");
	const normalizedFraction = (fraction + "00").slice(0, 2);
	return Number(whole) * 100 + Number(normalizedFraction);
}

export function formatMoney(cents) {
	return (cents / 100).toFixed(2);
}

import { toCents } from "./money.mjs";

function toLocalDateString(isoString) {
	const date = new Date(isoString);
	if (!Number.isFinite(date.getTime())) {
		return null;
	}
	const parts = new Intl.DateTimeFormat("en-CA", {
		timeZone: "Asia/Shanghai",
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).formatToParts(date);
	const values = Object.fromEntries(
		parts
			.filter((part) => part.type !== "literal")
			.map((part) => [part.type, part.value]),
	);
	if (!values.year || !values.month || !values.day) {
		return null;
	}
	return `${values.year}-${values.month}-${values.day}`;
}

export function reconcile(orders, events, { date }) {
	const orderMap = new Map();
	const rowsById = new Map();
	const dateCutoff = new Date(`${date}T15:59:59.999Z`).getTime();

	for (const order of orders) {
		if (toLocalDateString(order.createdAt) !== date) {
			continue;
		}
		orderMap.set(order.id, order);
		rowsById.set(order.id, {
			id: order.id,
			amountCents: toCents(order.amount),
			paymentCents: 0,
			refundCents: 0,
			netCents: 0,
			outstandingCents: 0,
			overpaidCents: 0,
			status: "unpaid",
		});
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seenEventIds = new Set();

	for (const event of events) {
		if (seenEventIds.has(event.eventId)) {
			ignored.duplicates += 1;
			continue;
		}
		seenEventIds.add(event.eventId);

		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			continue;
		}

		const occurredAt = new Date(event.occurredAt);
		if (!Number.isFinite(occurredAt.getTime()) || occurredAt.getTime() > dateCutoff) {
			ignored.afterCutoff += 1;
			continue;
		}

		const order = orderMap.get(event.orderId);
		if (!order) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}

		if (toLocalDateString(order.createdAt) !== date) {
			ignored.outsideOrderDate += 1;
			continue;
		}

		let amountCents;
		try {
			amountCents = toCents(event.amount);
		} catch {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}

		if (event.kind === "payment") {
			rowsById.get(event.orderId).paymentCents += amountCents;
		} else if (event.kind === "refund") {
			rowsById.get(event.orderId).refundCents += amountCents;
		}
	}

	const rows = [...rowsById.values()]
		.map((row) => {
			row.netCents = row.paymentCents - row.refundCents;
			row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
			row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
			if (row.refundCents > 0) {
				row.status = "refunded";
			} else if (row.paymentCents === 0) {
				row.status = "unpaid";
			} else if (row.paymentCents < row.amountCents) {
				row.status = "partial";
			} else if (row.paymentCents > row.amountCents) {
				row.status = "overpaid";
			} else {
				row.status = "paid";
			}
			return row;
		})
		.sort((a, b) => a.id.localeCompare(b.id, "en", { numeric: true }));

	const totals = {
		orderCount: rows.length,
		orderCents: rows.reduce((sum, row) => sum + row.amountCents, 0),
		paymentCents: rows.reduce((sum, row) => sum + row.paymentCents, 0),
		refundCents: rows.reduce((sum, row) => sum + row.refundCents, 0),
		netCents: rows.reduce((sum, row) => sum + row.netCents, 0),
		outstandingCents: rows.reduce((sum, row) => sum + row.outstandingCents, 0),
		overpaidCents: rows.reduce((sum, row) => sum + row.overpaidCents, 0),
	};

	return {
		date,
		timezone: "Asia/Shanghai",
		totals,
		orders: rows,
		ignored,
		issues,
	};
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { formatMoney } from "./money.mjs";
import { reconcile } from "./reconcile.mjs";

function buildSummary(report) {
	const formatCents = (cents) => `￥${(cents / 100).toFixed(2)}`;
	const needsAction = report.orders.filter(
		(order) => order.status === "unpaid" || order.status === "partial" || order.status === "refunded" || order.status === "overpaid",
	);
	const lines = [
		"# 2026-10-20 日结汇总",
		"",
		"## 合计",
		`- 订单数：${report.totals.orderCount}`,
		`- 订单金额：${formatCents(report.totals.orderCents)}`,
		`- 成功收款：${formatCents(report.totals.paymentCents)}`,
		`- 成功退款：${formatCents(report.totals.refundCents)}`,
		`- 净收款：${formatCents(report.totals.netCents)}`,
		`- 未收齐款：${formatCents(report.totals.outstandingCents)}`,
		`- 多付款：${formatCents(report.totals.overpaidCents)}`,
		"",
		"## 需要处理的订单",
	];

	if (needsAction.length === 0) {
		lines.push("- 无");
	} else {
		for (const order of needsAction) {
			const details = [
				`订单 ${order.id}`,
				`金额 ${formatCents(order.amountCents)}`,
				`已收 ${formatCents(order.paymentCents)}`,
				`已退 ${formatCents(order.refundCents)}`,
				`状态 ${order.status}`,
			];
			if (order.outstandingCents > 0) {
				details.push(`待催款 ${formatCents(order.outstandingCents)}`);
			}
			if (order.overpaidCents > 0) {
				details.push(`多付款 ${formatCents(order.overpaidCents)}`);
			}
			lines.push(`- ${details.join("；")}`);
		}
	}

	lines.push("", "## 人工核查");
	if (report.issues.length === 0) {
		lines.push("- 无");
	} else {
		for (const issue of report.issues) {
			const message = issue.code === "orphan_event" ? "找不到订单" : "金额不合法";
			lines.push(`- ${issue.eventId} / ${issue.orderId}：${issue.code}（${message}）`);
		}
	}

	lines.push(
		"",
		"## 已执行检查",
		"- 已按北京时间过滤订单创建日期和通知发生日期，仅统计 2026-10-20 00:00:00 到 23:59:59.999 之间的通知。",
		"- 已去重 eventId，并排除失败和等待中的通知，且不把超过截止时间的通知计入合计。",
		"- 已按金额规则校验非负两位小数，且将找不到订单和非法金额的通知单列人工核查，不计入财务总额。",
		"- 已分别统计成功收款、成功退款、净收款、未收齐款和多付款，并保留整数分精度。",
		"",
		"## 剩余限制",
		"- 本脚本只按 README 业务口径处理，未扩展渠道冲突重复、手续费和第二轮补单约定。",
		"- 本摘要仅为日结交接，最终催款、退款和核对仍需财务人工确认。",
	);

	return `${lines.join("\n")}\n`;
}

const args = process.argv.slice(2);
const options = Object.fromEntries(Array.from({ length: args.length / 2 }, (_, index) => [args[index * 2].slice(2), args[index * 2 + 1]]));
const orders = JSON.parse(readFileSync(options.orders, "utf8"));
const events = JSON.parse(readFileSync(options.events, "utf8"));
const report = reconcile(orders, events, { date: options.date });
mkdirSync(options.out, { recursive: true });
writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);
const csv = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
for (const row of report.orders) {
	csv.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents)].join(","));
}
writeFileSync(join(options.out, `${options.date}.csv`), `${csv.join("\n")}\n`);
writeFileSync(join(options.out, "summary.md"), buildSummary(report));
console.log(JSON.stringify({ json: `${options.out}/${options.date}.json`, csv: `${options.out}/${options.date}.csv`, summary: `${options.out}/summary.md` }));

import assert from "node:assert/strict";
import test from "node:test";
