function buildSummary(report) {
	const formatCents = (cents) => `￥${(cents / 100).toFixed(2)}`;
	const needsAction = report.orders.filter(
		(order) => order.status === "unpaid" || order.status === "partial" || order.status === "refunded" || order.status === "overpaid",
	);
	const lines = [
		"# 2026-10-20 日结汇总",
		"",
		"## 合计",
		`- 订单数：${report.totals.orderCount}`,
		`- 订单金额：${formatCents(report.totals.orderCents)}`,
		`- 成功收款：${formatCents(report.totals.paymentCents)}`,
		`- 成功退款：${formatCents(report.totals.refundCents)}`,
		`- 净收款：${formatCents(report.totals.netCents)}`,
		`- 未收齐款：${formatCents(report.totals.outstandingCents)}`,
		`- 多付款：${formatCents(report.totals.overpaidCents)}`,
		"",
		"## 需要处理的订单",
	];

	if (needsAction.length === 0) {
		lines.push("- 无");
	} else {
		for (const order of needsAction) {
			const details = [
				`订单 ${order.id}`,
				`金额 ${formatCents(order.amountCents)}`,
				`已收 ${formatCents(order.paymentCents)}`,
				`已退 ${formatCents(order.refundCents)}`,
				`状态 ${order.status}`,
			];
			if (order.outstandingCents > 0) {
				details.push(`待催款 ${formatCents(order.outstandingCents)}`);
			}
			if (order.overpaidCents > 0) {
				details.push(`多付款 ${formatCents(order.overpaidCents)}`);
			}
			lines.push(`- ${details.join("；")}`);
		}
	}

	lines.push("", "## 人工核查");
	if (report.issues.length === 0) {
		lines.push("- 无");
	} else {
		for (const issue of report.issues) {
			const message = issue.code === "orphan_event" ? "找不到订单" : "金额不合法";
			lines.push(`- ${issue.eventId} / ${issue.orderId}：${issue.code}（${message}）`);
		}
	}

