const report = reconcile(orders, events, { date: options.date });
mkdirSync(options.out, { recursive: true });
writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);
const csv = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
for (const row of report.orders) {
	csv.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents)].join(","));
}
writeFileSync(join(options.out, `${options.date}.csv`), `${csv.join("\n")}\n`);
console.log(JSON.stringify({ json: `${options.out}/${options.date}.json`, csv: `${options.out}/${options.date}.csv` }));

export function toCents(value) {
	return Math.trunc(Number(value) * 100);
}

export function formatMoney(cents) {
	return (cents / 100).toFixed(2);
}

import { toCents } from "./money.mjs";

export function reconcile(orders, events, { date }) {
	const rows = orders
		.filter((order) => order.createdAt.slice(0, 10) === date)
		.map((order) => {
			const paymentCents = events
				.filter((event) => event.orderId === order.id)
				.reduce((sum, event) => sum + toCents(event.amount), 0);
			const amountCents = toCents(order.amount);
			return {
				id: order.id,
				amountCents,
				paymentCents,
				refundCents: 0,
				netCents: paymentCents,
				outstandingCents: Math.max(amountCents - paymentCents, 0),
				overpaidCents: Math.max(paymentCents - amountCents, 0),
				status: paymentCents >= amountCents ? "paid" : "unpaid",
			};
		});
	const totals = { orderCount: rows.length };
	for (const key of ["amountCents", "paymentCents", "refundCents", "netCents", "outstandingCents", "overpaidCents"]) {
		totals[key === "amountCents" ? "orderCents" : key] = rows.reduce((sum, row) => sum + row[key], 0);
	}
	return {
		date,
		timezone: "UTC",
		totals,
		orders: rows,
		ignored: { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 },
		issues: [],
	};
}

