import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync, rmSync, existsSync } from "node:fs";
import { reconcile, dayBounds } from "../src/reconcile.mjs";
import { toCents, formatMoney } from "../src/money.mjs";
import { renderCsv } from "../src/output.mjs";
import { main, parseArgs } from "../src/cli.mjs";

const date = "2026-10-20";
const order = (id = "demo", amount = "10.00", createdAt = "2026-10-20T01:00:00Z") => ({ id, amount, createdAt });
const event = (patch = {}) => ({ eventId: "pay", orderId: "demo", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T02:00:00Z", ...patch });
const run = (orders, events) => reconcile(orders, events, { date });
const load = (path) => JSON.parse(readFileSync(new URL(`../${path}`, import.meta.url), "utf8"));

// First-round cases retained. Only additive zero-fee JSON/CSV schema expectations changed.
test("one simple payment", () => {
	const report = run([order()], [event()]);
	assert.equal(report.totals.netCents, 1000);
	assert.equal(report.orders[0].status, "paid");
});

test("real input: independently expected totals, rows, exclusions and issues", () => {
	const report = run(load("data/orders.json"), load("data/events.json"));
	assert.equal(report.timezone, "Asia/Shanghai");
	assert.deepEqual(report.totals, { orderCount: 7, orderCents: 55520, paymentCents: 43020, refundCents: 2000, netCents: 41020, outstandingCents: 15500, overpaidCents: 3000, feeCents: 0, settlementCents: 41020 });
	assert.deepEqual(report.orders.map((r) => [r.id, r.paymentCents, r.refundCents, r.netCents, r.outstandingCents, r.overpaidCents, r.status]), [
		["O1001", 19990, 0, 19990, 0, 0, "paid"], ["O1002", 3000, 0, 3000, 5000, 0, "partial"],
		["O1003", 5000, 2000, 3000, 0, 0, "refunded"], ["O1004", 15000, 0, 15000, 0, 3000, "overpaid"],
		["O1005", 0, 0, 0, 3500, 0, "unpaid"], ["O1006", 30, 0, 30, 0, 0, "paid"], ["O1007", 0, 0, 0, 7000, 0, "unpaid"],
	]);
	assert.deepEqual(report.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 2, outsideOrderDate: 0 });
	assert.deepEqual(report.issues, [{ eventId: "e09", orderId: "O9999", code: "orphan_event" }, { eventId: "e13", orderId: "O1005", code: "invalid_amount" }]);
});

test("Beijing creation boundary is inclusive to the millisecond, regardless of offset", () => {
	const report = run([
		order("before", "1", "2026-10-19T15:59:59.999Z"), order("start", "1", "2026-10-19T16:00:00Z"),
		order("end", "1", "2026-10-20T23:59:59.999+08:00"), order("after", "1", "2026-10-20T16:00:00Z"),
	], []);
	assert.deepEqual(report.orders.map((r) => r.id), ["end", "start"]);
});

test("cutoff uses occurredAt, not receivedAt, and includes final millisecond", () => {
	const report = run([order()], [
		event({ occurredAt: "2026-10-20T15:59:59.999Z", receivedAt: "2026-10-22T00:00:00Z" }),
		event({ eventId: "late", occurredAt: "2026-10-20T16:00:00Z" }),
	]);
	assert.equal(report.totals.paymentCents, 1000);
	assert.equal(report.ignored.afterCutoff, 1);
});

test("duplicate payment and refund each count once", () => {
	const payment = event();
	const refund = event({ eventId: "refund", kind: "refund", amount: "2" });
	const report = run([order()], [payment, payment, payment, refund, refund]);
	assert.equal(report.ignored.duplicates, 3);
	assert.equal(report.totals.paymentCents, 1000);
	assert.equal(report.totals.refundCents, 200);
});

test("filter precedence: dedup, state, cutoff, orphan, other date, amount", () => {
	const failed = event({ eventId: "failed", state: "failed", orderId: "missing", amount: "bad", occurredAt: "2026-10-21T00:00:00Z" });
	const report = run([order(), order("old", "1", "2026-10-18T00:00:00Z")], [
		failed, failed, event({ eventId: "pending", state: "pending", kind: "refund" }),
		event({ eventId: "late", orderId: "missing", occurredAt: "2026-10-21T00:00:00Z", amount: "bad" }),
		event({ eventId: "orphan", orderId: "missing", amount: "bad" }),
		event({ eventId: "outside", orderId: "old", amount: "bad" }),
		event({ eventId: "invalid", amount: "bad" }),
	]);
	assert.deepEqual(report.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 1, outsideOrderDate: 1 });
	assert.deepEqual(report.issues.map((i) => i.code), ["orphan_event", "invalid_amount"]);
	assert.equal(report.totals.paymentCents, 0);
});

test("refund does not become outstanding; refunded status has priority", () => {
	let row = run([order()], [event(), event({ eventId: "r", kind: "refund", amount: "4" })]).orders[0];
	assert.equal(row.netCents, 600);
	assert.equal(row.outstandingCents, 0);
	assert.equal(row.status, "refunded");
	row = run([order()], [event({ amount: "3" }), event({ eventId: "r", kind: "refund", amount: "4" })]).orders[0];
	assert.equal(row.netCents, -100);
	assert.equal(row.outstandingCents, 700);
	assert.equal(row.status, "refunded");
});

test("money parsing is exact including floating-point trap 0.29", () => {
	for (const [input, expected] of [["0", 0], ["0.10", 10], ["0.20", 20], ["0.29", 29], ["1.01", 101], ["199.90", 19990], ["01.2", 120]]) assert.equal(toCents(input), expected);
	const report = run([order("demo", "0.30")], [event({ amount: "0.10" }), event({ eventId: "b", amount: "0.20" })]);
	assert.equal(report.orders[0].netCents, 30);
	assert.equal(report.orders[0].status, "paid");
});

test("illegal amounts are isolated, never coerced into money", () => {
	const invalid = ["-5.00", "", " ", "1e2", "NaN", "Infinity", "1.001", ".50", "1.", "+1", " 1", "1\n", 12, null, "90071992547409.92"];
	for (const amount of invalid) assert.throws(() => toCents(amount));
	const report = run([order()], invalid.map((amount, i) => event({ eventId: String(i), amount })));
	assert.equal(report.issues.length, invalid.length);
	assert.ok(report.issues.every((i) => i.code === "invalid_amount"));
	assert.equal(report.totals.paymentCents, 0);
});

test("safe integer limits and sum overflow fail closed", () => {
	assert.equal(toCents("90071992547409.91"), Number.MAX_SAFE_INTEGER);
	assert.equal(formatMoney(Number.MAX_SAFE_INTEGER), "90071992547409.91");
	assert.throws(() => run([order()], [event({ amount: "90071992547409.91" }), event({ eventId: "extra", amount: "0.01" })]), /安全整数/);
	assert.throws(() => formatMoney(0.5));
});

test("CSV header, sorted IDs, escaping, negative net and fixed two decimals", () => {
	const report = run([order("z"), order('a,"b')], [event({ orderId: "z", kind: "refund", amount: "0.29" })]);
	assert.equal(renderCsv(report), 'order_id,amount,payment,refund,net,status,outstanding,overpaid,fee,settlement\n"a,""b",10.00,0.00,0.00,0.00,unpaid,10.00,0.00,0.00,0.00\nz,10.00,0.00,0.29,-0.29,refunded,10.00,0.00,0.00,-0.29\n');
});

test("empty data and input immutability", () => {
	assert.equal(run([], []).totals.netCents, 0);
	const orders = [order()]; const events = [event()];
	const snapshot = JSON.stringify({ orders, events });
	run(orders, events);
	assert.equal(JSON.stringify({ orders, events }), snapshot);
});

test("date and CLI validation", () => {
	for (const value of ["2026-02-30", "2026-13-20", "2026-1-1", "../bad"]) assert.throws(() => dayBounds(value));
	assert.throws(() => parseArgs([]));
	assert.throws(() => parseArgs(["--orders"]));
	assert.throws(() => parseArgs(["--unknown", "x"]));
	assert.throws(() => parseArgs(["--date", date, "--date", date]));
	assert.throws(() => run([order("a", "-1")], []));
	assert.throws(() => run([order("a", "1", "not-a-date")], []));
});

test("CLI creates missing output directory and writes all three consistent artifacts", () => {
	const out = "reports/test-cli-output/nested";
	try {
		const paths = main(["--orders", "data/orders.json", "--events", "data/events.json", "--date", date, "--out", out]);
		assert.ok(existsSync(paths.summary));
		const report = JSON.parse(readFileSync(paths.json, "utf8"));
		assert.equal(report.totals.netCents, 41020);
		assert.equal(readFileSync(paths.csv, "utf8"), renderCsv(report));
		const summary = readFileSync(paths.summary, "utf8");
		for (const value of ["430.20", "20.00", "410.20", "O1002", "O1004", "O1005", "O1007", "e09", "e13", "剩余限制"]) assert.ok(summary.includes(value), value);
	} finally { rmSync("reports/test-cli-output", { recursive: true, force: true }); }
});

