import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { reconcile } from "./reconcile.mjs";
import { validateFeeBps } from "./fees.mjs";
import { renderCsv, renderSummary } from "./output.mjs";

export function parseArgs(args) {
	const options = {};
	const required = ["orders", "events", "date", "out"];
	const allowed = [...required, "fee-bps"];
	for (let index = 0; index < args.length; index += 2) {
		const key = args[index].slice(2);
		const value = args[index + 1];
		if (!args[index].startsWith("--") || !allowed.includes(key) || options[key] !== undefined || !value || value.startsWith("--")) {
			throw new Error("参数错误：必须提供 --orders --events --date --out，可选 --fee-bps，且不可重复");
		}
		options[key] = value;
	}
	if (required.some((key) => !options[key])) throw new Error("必须提供 --orders --events --date --out");
	if (options["fee-bps"] !== undefined && !/^[0-9]+$/.test(options["fee-bps"])) throw new TypeError("fee-bps 必须为非负整数（万分比）");
	options.feeBps = validateFeeBps(Number(options["fee-bps"] ?? 0));
	return options;
}

export function main(args) {
	const options = parseArgs(args);
	const orders = JSON.parse(readFileSync(options.orders, "utf8"));
	const events = JSON.parse(readFileSync(options.events, "utf8"));
	const report = reconcile(orders, events, { date: options.date, feeBps: options.feeBps });
	const json = `${JSON.stringify(report, null, 2)}\n`;
	const csv = renderCsv(report);
	const summary = renderSummary(report);
	mkdirSync(options.out, { recursive: true });
	const paths = { json: join(options.out, `${options.date}.json`), csv: join(options.out, `${options.date}.csv`), summary: join(options.out, "summary.md") };
	writeFileSync(paths.json, json);
	writeFileSync(paths.csv, csv);
	writeFileSync(paths.summary, summary);
	return paths;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
	try { console.log(JSON.stringify(main(process.argv.slice(2)))); }
	catch (error) { console.error(`日结失败：${error.message}`); process.exitCode = 1; }
}

export function validateFeeBps(feeBps) {
	if (!Number.isSafeInteger(feeBps) || feeBps < 0) throw new TypeError("fee-bps 必须为非负安全整数（万分比）");
	return feeBps;
}

export function paymentFee(cents, feeBps) {
	// Positive integer arithmetic: round half up, per accepted payment.
	const fee = (BigInt(cents) * BigInt(feeBps) + 5000n) / 10000n;
	if (fee > BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError("手续费超出安全整数分范围");
	return Number(fee);
}

