		catch { issue("invalid_amount"); continue; }
		if (event.kind === "payment") row.paymentCents = addCents(row.paymentCents, cents);
		else if (event.kind === "refund") row.refundCents = addCents(row.refundCents, cents);
		else throw new TypeError(`不支持的通知类型：${event.kind}`);
	}
	const rows = [...selected.values()].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
	for (const row of rows) {
		row.netCents = row.paymentCents - row.refundCents;
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
		row.status = row.refundCents > 0 ? "refunded" : row.paymentCents === 0 ? "unpaid" : row.outstandingCents > 0 ? "partial" : row.overpaidCents > 0 ? "overpaid" : "paid";
	}
	const totals = { orderCount: rows.length };
	for (const key of ["amountCents", "paymentCents", "refundCents", "netCents", "outstandingCents", "overpaidCents"]) {
		totals[key === "amountCents" ? "orderCents" : key] = rows.reduce((sum, row) => addCents(sum, row[key]), 0);
	}
	return { date, timezone: "Asia/Shanghai", totals, orders: rows, ignored, issues };
}

