	const report = run([order()], [payment, payment, payment, refund, refund]);
	assert.equal(report.ignored.duplicates, 3);
	assert.equal(report.totals.paymentCents, 1000);
	assert.equal(report.totals.refundCents, 200);
});

test("filter precedence: dedup, state, cutoff, orphan, other date, amount", () => {
	const failed = event({ eventId: "failed", state: "failed", orderId: "missing", amount: "bad", occurredAt: "2026-10-21T00:00:00Z" });
	const report = run([order(), order("old", "1", "2026-10-18T00:00:00Z")], [
		failed, failed, event({ eventId: "pending", state: "pending", kind: "refund" }),
		event({ eventId: "late", orderId: "missing", occurredAt: "2026-10-21T00:00:00Z", amount: "bad" }),
