import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync, rmSync } from "node:fs";
import { reconcile } from "../src/reconcile.mjs";
import { main, parseArgs } from "../src/cli.mjs";
import { renderCsv } from "../src/output.mjs";

const date = "2026-10-20";
const order = { id: "a", amount: "10.00", createdAt: "2026-10-20T01:00:00Z" };
const event = (patch = {}) => ({ eventId: "p", orderId: "a", amount: "10.00", kind: "payment", state: "succeeded", occurredAt: "2026-10-20T02:00:00Z", ...patch });
const run = (events, feeBps = 60) => reconcile([order], events, { date, feeBps });
const load = (path) => JSON.parse(readFileSync(new URL(`../${path}`, import.meta.url), "utf8"));

test("updated input: full expected totals, per-order fees and all review items", () => {
	const report = reconcile(load("data/orders.json"), load("data/events-update.json"), { date, feeBps: 60 });
	assert.deepEqual(report.totals, { orderCount: 7, orderCents: 55520, paymentCents: 55520, refundCents: 6990, netCents: 48530, outstandingCents: 0, overpaidCents: 0, feeCents: 333, settlementCents: 48197 });
	assert.deepEqual(report.orders.map((r) => [r.id, r.paymentCents, r.refundCents, r.feeCents, r.settlementCents, r.status]), [
		["O1001", 19990, 4990, 120, 14880, "refunded"], ["O1002", 8000, 0, 48, 7952, "paid"],
		["O1003", 5000, 2000, 30, 2970, "refunded"], ["O1004", 12000, 0, 72, 11928, "paid"],
		["O1005", 3500, 0, 21, 3479, "paid"], ["O1006", 30, 0, 0, 30, "paid"], ["O1007", 7000, 0, 42, 6958, "paid"],
	]);
	assert.deepEqual(report.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 2, outsideOrderDate: 0 });
	assert.deepEqual(report.issues.map((i) => `${i.eventId}:${i.code}`).sort(), ["e05:conflicting_duplicate", "e09:orphan_event", "e13:invalid_amount"]);
	const prior = reconcile(load("data/orders.json"), load("data/events.json"), { date });
	for (const [key, delta] of Object.entries({ paymentCents: 12500, refundCents: 4990, netCents: 7510, feeCents: 333, settlementCents: 7177 })) assert.equal(report.totals[key] - prior.totals[key], delta);
});

test("each conflict field isolates all versions before filtering, in either order", () => {
	for (const patch of [{ orderId: "missing" }, { amount: "bad" }, { kind: "refund" }, { state: "failed" }, { occurredAt: "2026-10-21T00:00:00Z" }]) {
		const original = event(); const changed = event(patch);
		for (const events of [[original, original, changed], [changed, original, original]]) {
			const report = run(events);
			assert.equal(report.totals.paymentCents, 0);
			assert.equal(report.totals.refundCents, 0);
			assert.equal(report.totals.feeCents, 0);
			assert.equal(report.issues.length, 1);
			assert.equal(report.issues[0].code, "conflicting_duplicate");
			assert.deepEqual(report.ignored, { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 });
		}
	}
});

test("receivedAt is not a conflict field; identical payment and refund are counted once", () => {
	const payment = event(); const refund = event({ eventId: "r", kind: "refund", amount: "2.00" });
	const report = run([payment, { ...payment, receivedAt: "2026-11-01T00:00:00Z" }, refund, { ...refund, receivedAt: "2026-11-02T00:00:00Z" }]);
	assert.equal(report.ignored.duplicates, 2);
	assert.equal(report.issues.length, 0);
	assert.equal(report.totals.paymentCents, 1000);
	assert.equal(report.totals.refundCents, 200);
	assert.equal(report.totals.feeCents, 6);
	assert.equal(report.totals.settlementCents, 794);
});

test("conflicting ID does not quarantine independent payments on the same order", () => {
	const report = run([event(), event({ amount: "1.00" }), event({ eventId: "independent", amount: "12.00" })]);
	assert.equal(report.totals.paymentCents, 1200);
	assert.equal(report.totals.feeCents, 7);
	assert.equal(report.ignored.duplicates, 0);
});

test("fees round each payment separately, including exact half cents", () => {
	assert.equal(run([event({ amount: "0.83" }), event({ eventId: "b", amount: "0.83" })]).totals.feeCents, 0);
	assert.equal(run([event({ amount: "0.84" }), event({ eventId: "b", amount: "0.84" })]).totals.feeCents, 2);
	assert.equal(run([event({ amount: "2.50" })]).totals.feeCents, 2);
	assert.equal(run([event({ amount: "0.10" }), event({ eventId: "b", amount: "0.20" })]).totals.feeCents, 0);
});

test("refund does not charge or return fees, even on full refund", () => {
	const report = run([event(), event({ eventId: "r", kind: "refund" })]);
	assert.equal(report.totals.netCents, 0);
	assert.equal(report.totals.feeCents, 6);
	assert.equal(report.totals.settlementCents, -6);
	assert.equal(report.totals.outstandingCents, 0);
});

test("invalid, outside date, orphan, failed and late payments charge no fees", () => {
	const events = [event({ amount: "-1" }), event({ eventId: "f", state: "failed" }), event({ eventId: "pending", state: "pending" }), event({ eventId: "late", occurredAt: "2026-10-21T00:00:00Z" }), event({ eventId: "orphan", orderId: "missing" }), event({ eventId: "old", orderId: "old" })];
	const report = reconcile([order, { ...order, id: "old", createdAt: "2026-10-18T00:00:00Z" }], events, { date, feeBps: 60 });
	assert.equal(report.totals.feeCents, 0);
	assert.equal(report.totals.settlementCents, 0);
});

test("fee computation uses exact integer products even for large valid payments", () => {
	const report = run([event({ amount: "90071992547409.91" })]);
	assert.equal(report.totals.feeCents, Number((9007199254740991n * 60n + 5000n) / 10000n));
	assert.throws(() => run([event({ amount: "90071992547409.91" })], Number.MAX_SAFE_INTEGER), /安全整数/);
});

test("default zero fee preserves first-round financial meaning", () => {
	const report = reconcile([order], [event()], { date });
	assert.equal(report.totals.feeCents, 0);
	assert.equal(report.totals.settlementCents, report.totals.netCents);
	assert.equal(report.orders[0].feeCents, 0);
});

test("CLI validates optional fee-bps and retains required arguments", () => {
	const base = ["--orders", "data/orders.json", "--events", "data/events-update.json", "--date", date, "--out", "reports/test-update-output"];
	assert.doesNotThrow(() => parseArgs([...base, "--fee-bps", "60"]));
	for (const value of ["-1", "0.6", "NaN", "1e2", "", "9007199254740992"]) assert.throws(() => parseArgs([...base, "--fee-bps", value]));
	assert.throws(() => parseArgs([...base, "--fee-bps", "60", "--fee-bps", "0"]));
	assert.throws(() => parseArgs(["--fee-bps", "60"]));
	for (const value of [-1, NaN, Infinity, 0.5, "60"]) assert.throws(() => run([], value));
});

test("CLI updated file writes appended CSV fee and settlement and conflict explanation", () => {
	const out = "reports/test-update-output";
	try {
		const paths = main(["--orders", "data/orders.json", "--events", "data/events-update.json", "--date", date, "--out", out, "--fee-bps", "60"]);
		const report = JSON.parse(readFileSync(paths.json, "utf8"));
		assert.equal(report.totals.settlementCents, 48197);
		const csv = readFileSync(paths.csv, "utf8");
		assert.equal(csv, renderCsv(report));
		assert.equal(csv.split("\n")[0], "order_id,amount,payment,refund,net,status,outstanding,overpaid,fee,settlement");
		assert.ok(csv.includes("O1001,199.90,199.90,49.90,150.00,refunded,0.00,0.00,1.20,148.80"));
		const summary = readFileSync(paths.summary, "utf8");
		for (const text of ["555.20", "69.90", "3.33", "481.97", "e05", "e09", "e13", "conflicting_duplicate", "渠道账单", "逐笔", "剩余限制"]) assert.ok(summary.includes(text), text);
	} finally { rmSync(out, { recursive: true, force: true }); }
});

export function validateFeeBps(feeBps) {
	if (!Number.isSafeInteger(feeBps) || feeBps < 0) throw new TypeError("fee-bps 必须为非负安全整数（万分比）");
	return feeBps;
}

export function paymentFee(cents, feeBps) {
	// Positive integer arithmetic: round half up, per accepted payment.
	const fee = (BigInt(cents) * BigInt(feeBps) + 5000n) / 10000n;
	if (fee > BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError("手续费超出安全整数分范围");
	return Number(fee);
}

import { addCents, toCents } from "./money.mjs";
import { paymentFee, validateFeeBps } from "./fees.mjs";

export function dayBounds(date) {
	if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new TypeError("日期应为 YYYY-MM-DD");
	const utc = Date.parse(`${date}T00:00:00Z`);
	if (!Number.isFinite(utc) || new Date(utc).toISOString().slice(0, 10) !== date) throw new TypeError("无效日期");
	const start = utc - 8 * 60 * 60 * 1000;
	return { start, end: start + 24 * 60 * 60 * 1000 - 1 };
}

function timestamp(value) {
	if (typeof value !== "string" || !/(Z|[+-]\d{2}:\d{2})$/i.test(value) || !Number.isFinite(Date.parse(value))) {
		throw new TypeError(`时间必须包含明确时区：${value}`);
	}
	return Date.parse(value);
}

const conflictFields = ["orderId", "amount", "kind", "state", "occurredAt"];
function groupEvents(events) {
	const groups = new Map();
	for (const event of events) {
		const group = groups.get(event.eventId);
		if (!group) groups.set(event.eventId, { first: event, count: 1, conflict: false });
		else {
			group.count++;
			if (conflictFields.some((key) => event[key] !== group.first[key])) group.conflict = true;
		}
	}
	return groups.values();
}

export function reconcile(orders, events, { date, feeBps = 0 }) {
	validateFeeBps(feeBps);
	const { start, end } = dayBounds(date);
	const allOrders = new Map();
	const selected = new Map();
	for (const order of orders) {
		if (allOrders.has(order.id)) throw new Error(`重复订单 ID：${order.id}`);
		allOrders.set(order.id, order);
		const created = timestamp(order.createdAt);
		if (created < start || created > end) continue;
		selected.set(order.id, { id: order.id, amountCents: toCents(order.amount), paymentCents: 0, refundCents: 0, feeCents: 0 });
	}
	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	// Scan all versions before booking anything; an earlier version is not authoritative.
	for (const group of groupEvents(events)) {
		const event = group.first;
		const issue = (code) => issues.push({ eventId: event.eventId, orderId: event.orderId, code });
		if (group.conflict) { issue("conflicting_duplicate"); continue; }
		ignored.duplicates += group.count - 1;
		if (event.state !== "succeeded") { ignored.notSucceeded++; continue; }
		if (timestamp(event.occurredAt) > end) { ignored.afterCutoff++; continue; }
		if (!allOrders.has(event.orderId)) { issue("orphan_event"); continue; }
		const row = selected.get(event.orderId);
		if (!row) { ignored.outsideOrderDate++; continue; }
		let cents;
		try { cents = toCents(event.amount); }
		catch { issue("invalid_amount"); continue; }
		if (event.kind === "payment") {
			row.paymentCents = addCents(row.paymentCents, cents);
			row.feeCents = addCents(row.feeCents, paymentFee(cents, feeBps));
		} else if (event.kind === "refund") row.refundCents = addCents(row.refundCents, cents);
		else throw new TypeError(`不支持的通知类型：${event.kind}`);
	}
	const rows = [...selected.values()].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
	for (const row of rows) {
		row.netCents = row.paymentCents - row.refundCents;
		row.settlementCents = addCents(row.netCents, -row.feeCents);
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
		row.status = row.refundCents > 0 ? "refunded" : row.paymentCents === 0 ? "unpaid" : row.outstandingCents > 0 ? "partial" : row.overpaidCents > 0 ? "overpaid" : "paid";
	}
	const totals = { orderCount: rows.length };
	for (const key of ["amountCents", "paymentCents", "refundCents", "netCents", "outstandingCents", "overpaidCents", "feeCents", "settlementCents"]) {
		totals[key === "amountCents" ? "orderCents" : key] = rows.reduce((sum, row) => addCents(sum, row[key]), 0);
	}
	return { date, timezone: "Asia/Shanghai", feeBps, totals, orders: rows, ignored, issues };
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { reconcile } from "./reconcile.mjs";
import { validateFeeBps } from "./fees.mjs";
import { renderCsv, renderSummary } from "./output.mjs";

export function parseArgs(args) {
	const options = {};
	const required = ["orders", "events", "date", "out"];
	const allowed = [...required, "fee-bps"];
	for (let index = 0; index < args.length; index += 2) {
		const key = args[index].slice(2);
		const value = args[index + 1];
		if (!args[index].startsWith("--") || !allowed.includes(key) || options[key] !== undefined || !value || value.startsWith("--")) {
			throw new Error("参数错误：必须提供 --orders --events --date --out，可选 --fee-bps，且不可重复");
		}
		options[key] = value;
	}
	if (required.some((key) => !options[key])) throw new Error("必须提供 --orders --events --date --out");
	if (options["fee-bps"] !== undefined && !/^[0-9]+$/.test(options["fee-bps"])) throw new TypeError("fee-bps 必须为非负整数（万分比）");
	options.feeBps = validateFeeBps(Number(options["fee-bps"] ?? 0));
	return options;
}

export function main(args) {
	const options = parseArgs(args);
	const orders = JSON.parse(readFileSync(options.orders, "utf8"));
	const events = JSON.parse(readFileSync(options.events, "utf8"));
	const report = reconcile(orders, events, { date: options.date, feeBps: options.feeBps });
	const json = `${JSON.stringify(report, null, 2)}\n`;
	const csv = renderCsv(report);
	const summary = renderSummary(report);
	mkdirSync(options.out, { recursive: true });
	const paths = { json: join(options.out, `${options.date}.json`), csv: join(options.out, `${options.date}.csv`), summary: join(options.out, "summary.md") };
	writeFileSync(paths.json, json);
	writeFileSync(paths.csv, csv);
	writeFileSync(paths.summary, summary);
	return paths;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
	try { console.log(JSON.stringify(main(process.argv.slice(2)))); }
	catch (error) { console.error(`日结失败：${error.message}`); process.exitCode = 1; }
}

import { formatMoney } from "./money.mjs";

function csvCell(value) {
	const text = String(value);
	return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

export function renderCsv(report) {
	const lines = ["order_id,amount,payment,refund,net,status,outstanding,overpaid,fee,settlement"];
	for (const row of report.orders) {
		lines.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents), formatMoney(row.feeCents), formatMoney(row.settlementCents)].map(csvCell).join(","));
	}
	return `${lines.join("\n")}\n`;
}

export function renderSummary(report) {
	const money = (cents) => `${formatMoney(cents)} 元`;
	const t = report.totals;
	const lines = [
		`# ${report.date} 网店日结交接`, "",
		`口径：北京时间 ${report.date} 创建的订单，通知按 occurredAt 实际发生时间计入，截至当日 23:59:59.999（UTC+08:00）。不是全店所有历史订单的当日资金流水。receivedAt 和收到文件的时间均不作为截止依据。`, "",
		"## 合计", "",
		`- 订单数：${t.orderCount}；订单金额：${money(t.orderCents)}。`,
		`- 成功收款：${money(t.paymentCents)}；成功退款：${money(t.refundCents)}；净收款：${money(t.netCents)}。`,
		`- 手续费：${money(t.feeCents)}；预计到账净额：${money(t.settlementCents)}。费率为 ${report.feeBps} / 10000，仅对有效成功支付逐笔四舍五入到分后汇总；退款不产生手续费，也不退原手续费。`,
		`- netCents 仍为收款减退款；settlementCents = netCents - feeCents。`,
		`- 原订单未收齐：${money(t.outstandingCents)}；多付款：${money(t.overpaidCents)}。退款不重新形成欠款。`, "",
		"## 催款与多付款处理", "",
	];
	for (const row of report.orders) {
		if (row.outstandingCents > 0) lines.push(`- ${row.id}：订单 ${money(row.amountCents)}，成功收款 ${money(row.paymentCents)}，尚欠 ${money(row.outstandingCents)}。催款前核对截止后的支付与异常通知。`);
		if (row.overpaidCents > 0) lines.push(`- ${row.id}：成功收款 ${money(row.paymentCents)}，比订单金额多 ${money(row.overpaidCents)}，需核实并处理多付款；不要将待处理退款当成已退。`);
	}
	if (!t.outstandingCents && !t.overpaidCents) lines.push("- 按当前有效入账通知，无未收齐或多付款订单；人工核查项仍需处理，不能据此认定渠道账单已核销。");
	lines.push("", "## 已退款（与欠款分开）", "");
	for (const row of report.orders.filter((row) => row.refundCents > 0)) {
		lines.push(`- ${row.id}：已成功退款 ${money(row.refundCents)}，净收款 ${money(row.netCents)}，原订单未收齐 ${money(row.outstandingCents)}；保留手续费 ${money(row.feeCents)}。`);
	}
	if (!t.refundCents) lines.push("- 无成功退款。");
	lines.push("", "## 人工核查（未计入任何财务合计，也不计手续费）", "");
	const explanations = {
		orphan_event: "找不到订单，核对订单归属",
		invalid_amount: "金额不合法，核对渠道原始金额",
		conflicting_duplicate: "这组通知有矛盾，需要核对渠道账单；整个 ID 所有版本已隔离，不默认任一版本正确",
	};
	for (const issue of report.issues) {
		lines.push(`- ${issue.eventId} / ${issue.orderId}（${issue.code}）：${explanations[issue.code]}。确认后提供有效数据重新对账，不能凭脚本推断真实收款。`);
	}
	if (!report.issues.length) lines.push("- 无。");
	lines.push("", "## 排除与检查", "",
		`- 先按 ID 检查冲突并整组隔离，再执行普通去重、状态、截止时间、订单归属、金额验证。普通重复 ${report.ignored.duplicates} 条，非成功 ${report.ignored.notSucceeded} 条，截止后 ${report.ignored.afterCutoff} 条，其他日期订单 ${report.ignored.outsideOrderDate} 条；冲突组不计入普通重复数。`,
		"- 冲突比较订单、金额、类型、状态和发生时间；receivedAt 不参与比较。冲突按 ID 隔离，不影响同订单其他独立通知。",
		"- 金额按整数分计算，手续费乘积及四舍五入采用精确整数运算；JSON 保留整数分，CSV 固定两位小数（元），订单按 ID 排序。",
		"- 第一轮回归用例继续保留；新增测试覆盖冲突的五个字段及前置优先级、接收时间差异、逐笔舍入、退款不退手续费、零费率兼容和新 CLI/输出字段。实际执行结果见本次交付记录。", "",
		"## 剩余限制", "",
		"- 仅依据本次输入的订单与通知，不代表已与银行或支付渠道账单逐笔核销；预计到账不是银行实收。不会自动催款或退款，不联系财务、不改动真实业务系统。",
		"- 金额超出安全整数分范围不接受；合计或手续费溢出、非法订单金额、无明确时区的时间或未知通知类型会报错，避免生成不可信结果。", "");
	return lines.join("\n");
}

import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync, rmSync, existsSync } from "node:fs";
import { reconcile, dayBounds } from "../src/reconcile.mjs";
import { toCents, formatMoney } from "../src/money.mjs";
import { renderCsv } from "../src/output.mjs";
import { main, parseArgs } from "../src/cli.mjs";

const date = "2026-10-20";
const order = (id = "demo", amount = "10.00", createdAt = "2026-10-20T01:00:00Z") => ({ id, amount, createdAt });
const event = (patch = {}) => ({ eventId: "pay", orderId: "demo", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T02:00:00Z", ...patch });
const run = (orders, events) => reconcile(orders, events, { date });
const load = (path) => JSON.parse(readFileSync(new URL(`../${path}`, import.meta.url), "utf8"));

// First-round cases retained. Only additive zero-fee JSON/CSV schema expectations changed.
test("one simple payment", () => {
	const report = run([order()], [event()]);
	assert.equal(report.totals.netCents, 1000);
	assert.equal(report.orders[0].status, "paid");
});

test("real input: independently expected totals, rows, exclusions and issues", () => {
	const report = run(load("data/orders.json"), load("data/events.json"));
	assert.equal(report.timezone, "Asia/Shanghai");
	assert.deepEqual(report.totals, { orderCount: 7, orderCents: 55520, paymentCents: 43020, refundCents: 2000, netCents: 41020, outstandingCents: 15500, overpaidCents: 3000, feeCents: 0, settlementCents: 41020 });
	assert.deepEqual(report.orders.map((r) => [r.id, r.paymentCents, r.refundCents, r.netCents, r.outstandingCents, r.overpaidCents, r.status]), [
		["O1001", 19990, 0, 19990, 0, 0, "paid"], ["O1002", 3000, 0, 3000, 5000, 0, "partial"],
		["O1003", 5000, 2000, 3000, 0, 0, "refunded"], ["O1004", 15000, 0, 15000, 0, 3000, "overpaid"],
		["O1005", 0, 0, 0, 3500, 0, "unpaid"], ["O1006", 30, 0, 30, 0, 0, "paid"], ["O1007", 0, 0, 0, 7000, 0, "unpaid"],
	]);
	assert.deepEqual(report.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 2, outsideOrderDate: 0 });
	assert.deepEqual(report.issues, [{ eventId: "e09", orderId: "O9999", code: "orphan_event" }, { eventId: "e13", orderId: "O1005", code: "invalid_amount" }]);
});

test("Beijing creation boundary is inclusive to the millisecond, regardless of offset", () => {
	const report = run([
		order("before", "1", "2026-10-19T15:59:59.999Z"), order("start", "1", "2026-10-19T16:00:00Z"),
		order("end", "1", "2026-10-20T23:59:59.999+08:00"), order("after", "1", "2026-10-20T16:00:00Z"),
	], []);
	assert.deepEqual(report.orders.map((r) => r.id), ["end", "start"]);
});

test("cutoff uses occurredAt, not receivedAt, and includes final millisecond", () => {
	const report = run([order()], [
		event({ occurredAt: "2026-10-20T15:59:59.999Z", receivedAt: "2026-10-22T00:00:00Z" }),
		event({ eventId: "late", occurredAt: "2026-10-20T16:00:00Z" }),
	]);
	assert.equal(report.totals.paymentCents, 1000);
	assert.equal(report.ignored.afterCutoff, 1);
});

test("duplicate payment and refund each count once", () => {
	const payment = event();
	const refund = event({ eventId: "refund", kind: "refund", amount: "2" });
	const report = run([order()], [payment, payment, payment, refund, refund]);
	assert.equal(report.ignored.duplicates, 3);
	assert.equal(report.totals.paymentCents, 1000);
	assert.equal(report.totals.refundCents, 200);
});

test("filter precedence: dedup, state, cutoff, orphan, other date, amount", () => {
	const failed = event({ eventId: "failed", state: "failed", orderId: "missing", amount: "bad", occurredAt: "2026-10-21T00:00:00Z" });
	const report = run([order(), order("old", "1", "2026-10-18T00:00:00Z")], [
		failed, failed, event({ eventId: "pending", state: "pending", kind: "refund" }),
		event({ eventId: "late", orderId: "missing", occurredAt: "2026-10-21T00:00:00Z", amount: "bad" }),
		event({ eventId: "orphan", orderId: "missing", amount: "bad" }),
		event({ eventId: "outside", orderId: "old", amount: "bad" }),
		event({ eventId: "invalid", amount: "bad" }),
	]);
	assert.deepEqual(report.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 1, outsideOrderDate: 1 });
	assert.deepEqual(report.issues.map((i) => i.code), ["orphan_event", "invalid_amount"]);
	assert.equal(report.totals.paymentCents, 0);
});

test("refund does not become outstanding; refunded status has priority", () => {
	let row = run([order()], [event(), event({ eventId: "r", kind: "refund", amount: "4" })]).orders[0];
	assert.equal(row.netCents, 600);
	assert.equal(row.outstandingCents, 0);
	assert.equal(row.status, "refunded");
	row = run([order()], [event({ amount: "3" }), event({ eventId: "r", kind: "refund", amount: "4" })]).orders[0];
	assert.equal(row.netCents, -100);
	assert.equal(row.outstandingCents, 700);
	assert.equal(row.status, "refunded");
});

test("money parsing is exact including floating-point trap 0.29", () => {
	for (const [input, expected] of [["0", 0], ["0.10", 10], ["0.20", 20], ["0.29", 29], ["1.01", 101], ["199.90", 19990], ["01.2", 120]]) assert.equal(toCents(input), expected);
	const report = run([order("demo", "0.30")], [event({ amount: "0.10" }), event({ eventId: "b", amount: "0.20" })]);
	assert.equal(report.orders[0].netCents, 30);
	assert.equal(report.orders[0].status, "paid");
});

test("illegal amounts are isolated, never coerced into money", () => {
	const invalid = ["-5.00", "", " ", "1e2", "NaN", "Infinity", "1.001", ".50", "1.", "+1", " 1", "1\n", 12, null, "90071992547409.92"];
	for (const amount of invalid) assert.throws(() => toCents(amount));
	const report = run([order()], invalid.map((amount, i) => event({ eventId: String(i), amount })));
	assert.equal(report.issues.length, invalid.length);
	assert.ok(report.issues.every((i) => i.code === "invalid_amount"));
	assert.equal(report.totals.paymentCents, 0);
});

test("safe integer limits and sum overflow fail closed", () => {
	assert.equal(toCents("90071992547409.91"), Number.MAX_SAFE_INTEGER);
	assert.equal(formatMoney(Number.MAX_SAFE_INTEGER), "90071992547409.91");
	assert.throws(() => run([order()], [event({ amount: "90071992547409.91" }), event({ eventId: "extra", amount: "0.01" })]), /安全整数/);
	assert.throws(() => formatMoney(0.5));
});

test("CSV header, sorted IDs, escaping, negative net and fixed two decimals", () => {
	const report = run([order("z"), order('a,"b')], [event({ orderId: "z", kind: "refund", amount: "0.29" })]);
	assert.equal(renderCsv(report), 'order_id,amount,payment,refund,net,status,outstanding,overpaid,fee,settlement\n"a,""b",10.00,0.00,0.00,0.00,unpaid,10.00,0.00,0.00,0.00\nz,10.00,0.00,0.29,-0.29,refunded,10.00,0.00,0.00,-0.29\n');
});

test("empty data and input immutability", () => {
	assert.equal(run([], []).totals.netCents, 0);
	const orders = [order()]; const events = [event()];
	const snapshot = JSON.stringify({ orders, events });
	run(orders, events);
	assert.equal(JSON.stringify({ orders, events }), snapshot);
});

test("date and CLI validation", () => {
	for (const value of ["2026-02-30", "2026-13-20", "2026-1-1", "../bad"]) assert.throws(() => dayBounds(value));
	assert.throws(() => parseArgs([]));
	assert.throws(() => parseArgs(["--orders"]));
	assert.throws(() => parseArgs(["--unknown", "x"]));
	assert.throws(() => parseArgs(["--date", date, "--date", date]));
	assert.throws(() => run([order("a", "-1")], []));
	assert.throws(() => run([order("a", "1", "not-a-date")], []));
});

test("CLI creates missing output directory and writes all three consistent artifacts", () => {
	const out = "reports/test-cli-output/nested";
	try {
		const paths = main(["--orders", "data/orders.json", "--events", "data/events.json", "--date", date, "--out", out]);
		assert.ok(existsSync(paths.summary));
		const report = JSON.parse(readFileSync(paths.json, "utf8"));
		assert.equal(report.totals.netCents, 41020);
		assert.equal(readFileSync(paths.csv, "utf8"), renderCsv(report));
		const summary = readFileSync(paths.summary, "utf8");
		for (const value of ["430.20", "20.00", "410.20", "O1002", "O1004", "O1005", "O1007", "e09", "e13", "剩余限制"]) assert.ok(summary.includes(value), value);
	} finally { rmSync("reports/test-cli-output", { recursive: true, force: true }); }
