	assert.equal(toCents("12.3"), 1230);
	assert.equal(formatMoney(-5), "-0.05");
	for (const value of ["", "-1.00", "1e2", "NaN", "1.234", " 1.00", 1]) {
		assert.throws(() => toCents(value));
	}
});

test("uses the Beijing order day and the inclusive end-of-day cutoff", () => {
	const orders = [
		{ id: "start", amount: "1.00", createdAt: "2026-10-19T16:00:00.000Z" },
		{ id: "end", amount: "1.00", createdAt: "2026-10-20T15:59:59.999Z" },
		{ id: "next", amount: "1.00", createdAt: "2026-10-20T16:00:00.000Z" },
	];
	const events = [
		event("p1", "start", "payment", "succeeded", "1.00", "2026-10-20T15:59:59.999Z"),
		event("p2", "end", "payment", "succeeded", "1.00", "2026-10-20T16:00:00.000Z"),
		event("p3", "next", "payment", "succeeded", "1.00", "2026-10-20T10:00:00Z"),
	];
	const report = reconcile(orders, events, { date: "2026-10-20" });
	assert.deepEqual(report.orders.map((row) => row.id), ["end", "start"]);
	assert.equal(report.timezone, "Asia/Shanghai");
	assert.equal(report.totals.paymentCents, 100);
	assert.deepEqual(report.ignored, { duplicates: 0, notSucceeded: 0, afterCutoff: 1, outsideOrderDate: 1 });
});

test("deduplicates and separates refunds, ignored notices and review issues", () => {
	const orders = [
		{ id: "A", amount: "10.00", createdAt: "2026-10-20T01:00:00Z" },
		{ id: "B", amount: "5.00", createdAt: "2026-10-20T01:00:00Z" },
	];
	const events = [
		event("pay", "A", "payment", "succeeded", "12.00"),
		event("pay", "A", "payment", "succeeded", "12.00"),
		event("refund", "A", "refund", "succeeded", "3.00"),
		event("failed", "B", "payment", "failed", "5.00"),
		event("orphan", "missing", "payment", "succeeded", "9.00"),
		event("bad", "B", "payment", "succeeded", "1.001"),
	];
	const report = reconcile(orders, events, { date: "2026-10-20" });
	assert.deepEqual(report.totals, {
		orderCount: 2, orderCents: 1500, paymentCents: 1200, refundCents: 300,
		netCents: 900, outstandingCents: 500, overpaidCents: 200,
	});
	assert.equal(report.orders[0].status, "refunded");
	assert.equal(report.orders[0].outstandingCents, 0, "refund must not become outstanding");
	assert.equal(report.orders[1].status, "unpaid");
	assert.equal(report.ignored.duplicates, 1);
	assert.equal(report.ignored.notSucceeded, 1);
	assert.deepEqual(report.issues, [
		{ eventId: "orphan", orderId: "missing", code: "orphan_event" },
		{ eventId: "bad", orderId: "B", code: "invalid_amount" },
	]);
});

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { formatMoney } from "./money.mjs";
import { reconcile } from "./reconcile.mjs";

const args = process.argv.slice(2);
const options = {};
for (let index = 0; index < args.length; index += 2) {
	if (!args[index]?.startsWith("--") || args[index + 1] === undefined) throw new Error("参数必须使用 --名称 值");
	options[args[index].slice(2)] = args[index + 1];
}
for (const name of ["orders", "events", "date", "out"]) {
	if (!options[name]) throw new Error(`缺少必填参数 --${name}`);
}

const orders = JSON.parse(readFileSync(options.orders, "utf8"));
const events = JSON.parse(readFileSync(options.events, "utf8"));
const report = reconcile(orders, events, { date: options.date });
mkdirSync(options.out, { recursive: true });
const jsonPath = join(options.out, `${options.date}.json`);
const csvPath = join(options.out, `${options.date}.csv`);
const summaryPath = join(options.out, "summary.md");
writeFileSync(jsonPath, `${JSON.stringify(report, null, 2)}\n`);

const csv = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
for (const row of report.orders) {
	csv.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents)].join(","));
}
writeFileSync(csvPath, `${csv.join("\n")}\n`);

const money = (cents) => `¥${formatMoney(cents)}`;
const outstanding = report.orders.filter((row) => row.outstandingCents > 0);
const overpaid = report.orders.filter((row) => row.overpaidCents > 0);
const refunded = report.orders.filter((row) => row.refundCents > 0);
const lines = [
	`# ${report.date} 北京时间日结对账`,
	"",
	"## 合计",
	"",
	`- 当日创建订单：${report.totals.orderCount} 笔，订单金额 ${money(report.totals.orderCents)}`,
	`- 成功收款：${money(report.totals.paymentCents)}`,
	`- 成功退款：${money(report.totals.refundCents)}`,
	`- 净收款（收款减退款）：${money(report.totals.netCents)}`,
	`- 尚未收齐：${money(report.totals.outstandingCents)}；多付款：${money(report.totals.overpaidCents)}`,
	"",
	"## 运营处理",
	"",
	...(outstanding.length ? outstanding.map((row) => `- 催款：${row.id} 尚欠 ${money(row.outstandingCents)}`) : ["- 无需催款的订单"]),
	...(overpaid.length ? overpaid.map((row) => `- 处理多付款：${row.id} 多付 ${money(row.overpaidCents)}`) : ["- 无多付款订单"]),
	...(refunded.length ? refunded.map((row) => `- 已退款（与欠款分列）：${row.id} 成功退款 ${money(row.refundCents)}`) : ["- 无成功退款订单"]),
	"",
	"## 人工核查",
	"",
	...(report.issues.length ? report.issues.map((issue) => `- ${issue.eventId} / ${issue.orderId}：${issue.code === "orphan_event" ? "找不到订单（orphan_event）" : "金额格式不合法（invalid_amount）"}`) : ["- 无"]),
	"",
	"## 已执行检查",
	"",
	`- 按 Asia/Shanghai 筛选订单，并以当日 23:59:59.999 为通知截止时间；截止后忽略 ${report.ignored.afterCutoff} 条。`,
	`- 按 eventId 去重，重复通知忽略 ${report.ignored.duplicates} 条。`,
	`- 只入账 succeeded，失败或等待通知忽略 ${report.ignored.notSucceeded} 条。`,
	`- 其他日期订单的通知忽略 ${report.ignored.outsideOrderDate} 条；孤儿和非法金额单列，不进入合计。`,
	"- 所有金额先严格校验十进制字符串，再转换为整数分计算；退款与未收齐款分别计算。",
	"",
	"## 限制",
	"",
	`- 本报表只反映 ${options.events} 当前快照中、截止时间前已成功的通知；截止后到达或状态后续变更的通知需下一轮重新生成。`,
	"- “催款”和“处理多付款”是运营待办提示，脚本不会自动发起催款或退款。",
	"",
];
writeFileSync(summaryPath, lines.join("\n"));
console.log(JSON.stringify({ json: jsonPath, csv: csvPath, summary: summaryPath }));

