import { toCents } from "./money.mjs";

function parseTime(value, field) {
	const timestamp = Date.parse(value);
	if (!Number.isFinite(timestamp)) throw new TypeError(`Invalid ${field}: ${JSON.stringify(value)}`);
	return timestamp;
}

function dateWindow(date) {
	if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new TypeError(`Invalid date: ${JSON.stringify(date)}`);
	const start = Date.parse(`${date}T00:00:00+08:00`);
	if (!Number.isFinite(start)) throw new TypeError(`Invalid date: ${JSON.stringify(date)}`);
	return { start, end: start + 24 * 60 * 60 * 1000 - 1 };
}

function eventSignature(event) {
	return JSON.stringify([event.orderId, event.amount, event.kind, event.state, event.occurredAt]);
}

function calculateFee(cents, feeBps) {
	const fee = (BigInt(cents) * BigInt(feeBps) + 5000n) / 10000n;
	if (fee > BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError("Calculated fee is too large");
	return Number(fee);
}

export function reconcile(orders, events, { date, feeBps = 0 }) {
	if (!Number.isSafeInteger(feeBps) || feeBps < 0) throw new TypeError("feeBps must be a non-negative integer");
	const { start, end } = dateWindow(date);
	const allOrders = new Map();
	const rowsById = new Map();

	for (const order of orders) {
		allOrders.set(order.id, order);
		const createdAt = parseTime(order.createdAt, "order.createdAt");
		if (createdAt < start || createdAt > end) continue;
		const amountCents = toCents(order.amount);
		rowsById.set(order.id, { id: order.id, amountCents, paymentCents: 0, refundCents: 0, feeCents: 0 });
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const eventGroups = new Map();
	for (const event of events) {
		if (!eventGroups.has(event.eventId)) eventGroups.set(event.eventId, []);
		eventGroups.get(event.eventId).push(event);
	}

	for (const [eventId, versions] of eventGroups) {
		const signatures = new Set(versions.map(eventSignature));
		if (signatures.size > 1) {
			issues.push({ eventId, orderId: versions[0].orderId, code: "conflicting_duplicate" });
			continue;
		}
		ignored.duplicates += versions.length - 1;
		const event = versions[0];
		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			continue;
		}
		if (parseTime(event.occurredAt, "event.occurredAt") > end) {
			ignored.afterCutoff += 1;
			continue;
		}
		const order = allOrders.get(event.orderId);
		if (!order) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}
		const row = rowsById.get(event.orderId);
		if (!row) {
			ignored.outsideOrderDate += 1;
			continue;
		}
		let amountCents;
		try {
			amountCents = toCents(event.amount);
		} catch {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}
		if (event.kind === "payment") {
			row.paymentCents += amountCents;
			row.feeCents += calculateFee(amountCents, feeBps);
		} else if (event.kind === "refund") {
			row.refundCents += amountCents;
		}
	}

	const rows = [...rowsById.values()].sort((a, b) => a.id.localeCompare(b.id)).map((row) => {
		const netCents = row.paymentCents - row.refundCents;
		const settlementCents = netCents - row.feeCents;
		const outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		const overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
		let status;
		if (row.refundCents > 0) status = "refunded";
		else if (row.paymentCents === 0) status = "unpaid";
		else if (row.paymentCents < row.amountCents) status = "partial";
		else if (row.paymentCents > row.amountCents) status = "overpaid";
		else status = "paid";
		return { ...row, netCents, settlementCents, outstandingCents, overpaidCents, status };
	});

	const totals = { orderCount: rows.length };
	for (const key of ["amountCents", "paymentCents", "refundCents", "netCents", "outstandingCents", "overpaidCents", "feeCents", "settlementCents"]) {
		totals[key === "amountCents" ? "orderCents" : key] = rows.reduce((sum, row) => sum + row[key], 0);
	}
	return { date, timezone: "Asia/Shanghai", totals, orders: rows, ignored, issues };
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
