import { feeCentsFor, isValidAmount, toCents } from "./money.mjs";

const BEIJING_OFFSET_MS = 8 * 60 * 60 * 1000;

export function beijingDate(iso) {
	const ms = Date.parse(iso);
	if (Number.isNaN(ms)) return null;
	return new Date(ms + BEIJING_OFFSET_MS).toISOString().slice(0, 10);
}

export function endOfBeijingDay(date) {
	const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
	if (!match) return Number.NaN;
	const year = Number(match[1]);
	const month = Number(match[2]);
	const day = Number(match[3]);
	return Date.UTC(year, month - 1, day, 23, 59, 59, 999) - BEIJING_OFFSET_MS;
}

export function assemble(orders, events, options = {}) {
	const { date } = options;
	if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
		throw new Error("date 必须是 YYYY-MM-DD");
	}
	const includeFee = Object.prototype.hasOwnProperty.call(options, "feeBps");
	const feeBps = includeFee ? options.feeBps : 0;
	if (includeFee && (!Number.isInteger(feeBps) || feeBps < 0)) {
		throw new Error("feeBps 必须是非负整数");
	}
	const cutoff = endOfBeijingDay(date);
	if (Number.isNaN(cutoff)) {
		throw new Error("无法计算截止时间");
	}

	const ordersById = new Map();
	for (const order of orders) {
		if (!ordersById.has(order.id)) ordersById.set(order.id, order);
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const paymentByOrder = new Map();
	const refundByOrder = new Map();
	const feeByOrder = new Map();
	const audit = {
		duplicates: [],
		notSucceeded: [],
		afterCutoff: [],
		outsideOrderDate: [],
		manualReview: [],
		feeBps: includeFee ? feeBps : null,
		excludedOrders: orders
			.filter((order) => beijingDate(order.createdAt) !== date)
			.map((order) => ({ id: order.id, createdAt: order.createdAt, beijingDate: beijingDate(order.createdAt) })),
	};

	const groups = [];
	const groupIndex = new Map();
	events.forEach((event, index) => {
		const key = event.eventId === undefined || event.eventId === null ? `\0missing:${index}` : String(event.eventId);
		if (!groupIndex.has(key)) {
			groupIndex.set(key, groups.length);
			groups.push(event);
			groups[groupIndex.get(key)] = { eventId: event.eventId, events: [event] };
		} else {
			groups[groupIndex.get(key)].events.push(event);
		}
	});

	for (const group of groups) {
		const signatures = new Set(group.events.map(eventSignature));
		if (group.events.length > 1 && signatures.size > 1) {
			const issue = { eventId: group.eventId, orderId: group.events[0].orderId, code: "conflicting_duplicate" };
			issues.push(issue);
			audit.manualReview.push({
				...issue,
				amount: null,
				versions: group.events.map((event) => ({
					orderId: event.orderId,
					amount: event.amount,
					kind: event.kind,
					state: event.state,
					occurredAt: event.occurredAt,
				})),
			});
			continue;
		}
		if (group.events.length > 1) {
			ignored.duplicates += group.events.length - 1;
			for (const extra of group.events.slice(1)) {
				audit.duplicates.push({ eventId: extra.eventId, orderId: extra.orderId });
			}
		}

		const event = group.events[0];
		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			audit.notSucceeded.push({ eventId: event.eventId, orderId: event.orderId, state: event.state ?? "" });
			continue;
		}

		const occurredMs = Date.parse(event.occurredAt);
		if (Number.isNaN(occurredMs) || occurredMs > cutoff) {
			ignored.afterCutoff += 1;
			audit.afterCutoff.push({ eventId: event.eventId, orderId: event.orderId, occurredAt: event.occurredAt });
			continue;
		}

		const order = ordersById.get(event.orderId);
		if (!order) {
			addIssue(event, "orphan_event");
			continue;
		}
		if (beijingDate(order.createdAt) !== date) {
			ignored.outsideOrderDate += 1;
			audit.outsideOrderDate.push({ eventId: event.eventId, orderId: event.orderId });
			continue;
		}

		const cents = readEventCents(event.amount);
		if (cents === null) {
			addIssue(event, "invalid_amount");
			continue;
		}

		if (event.kind === "payment") {
			paymentByOrder.set(event.orderId, (paymentByOrder.get(event.orderId) ?? 0) + cents);
			if (includeFee) {
				feeByOrder.set(event.orderId, (feeByOrder.get(event.orderId) ?? 0) + feeCentsFor(cents, feeBps));
			}
		} else if (event.kind === "refund") {
			refundByOrder.set(event.orderId, (refundByOrder.get(event.orderId) ?? 0) + cents);
		}
	}

	const rows = orders
		.filter((order) => beijingDate(order.createdAt) === date)
		.map((order) => {
			if (!isValidAmount(order.amount)) {
				throw new Error(`订单 ${order.id} 金额不合法`);
			}
			const amountCents = toCents(order.amount);
			const paymentCents = paymentByOrder.get(order.id) ?? 0;
			const refundCents = refundByOrder.get(order.id) ?? 0;
			const netCents = paymentCents - refundCents;
			const row = {
				id: order.id,
				amountCents,
				paymentCents,
				refundCents,
				netCents,
				outstandingCents: Math.max(amountCents - paymentCents, 0),
				overpaidCents: Math.max(paymentCents - amountCents, 0),
				status: statusFor(amountCents, paymentCents, refundCents),
			};
			if (includeFee) {
				row.feeCents = feeByOrder.get(order.id) ?? 0;
				row.settlementCents = netCents - row.feeCents;
			}
			return row;
		})
		.sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));

	const totals = {
		orderCount: rows.length,
		orderCents: 0,
		paymentCents: 0,
		refundCents: 0,
		netCents: 0,
		outstandingCents: 0,
		overpaidCents: 0,
	};
	if (includeFee) {
		totals.feeCents = 0;
		totals.settlementCents = 0;
	}
	for (const row of rows) {
		totals.orderCents += row.amountCents;
		totals.paymentCents += row.paymentCents;
		totals.refundCents += row.refundCents;
		totals.netCents += row.netCents;
		totals.outstandingCents += row.outstandingCents;
		totals.overpaidCents += row.overpaidCents;
		if (includeFee) {
			totals.feeCents += row.feeCents;
			totals.settlementCents += row.settlementCents;
		}
	}

	return {
		report: { date, timezone: "Asia/Shanghai", totals, orders: rows, ignored, issues },
		audit,
	};

	function addIssue(event, code) {
		const issue = { eventId: event.eventId, orderId: event.orderId, code };
		issues.push(issue);
		audit.manualReview.push({ ...issue, amount: event.amount ?? null });
	}
}

export function reconcile(orders, events, options) {
	return assemble(orders, events, options).report;
}

function eventSignature(event) {
	return JSON.stringify([event.orderId ?? null, event.amount ?? null, event.kind ?? null, event.state ?? null, event.occurredAt ?? null]);
}

function readEventCents(value) {
	if (!isValidAmount(value)) return null;
	try {
		return toCents(value);
	} catch {
		return null;
	}
}

function statusFor(amountCents, paymentCents, refundCents) {
	if (refundCents > 0) return "refunded";
	if (paymentCents === 0) return "unpaid";
	if (paymentCents < amountCents) return "partial";
	if (paymentCents > amountCents) return "overpaid";
	return "paid";
}

