import { feeCentsFor, isValidAmount, toCents } from "./money.mjs";

const BEIJING_OFFSET_MS = 8 * 60 * 60 * 1000;

export function beijingDate(iso) {
	const ms = Date.parse(iso);
	if (Number.isNaN(ms)) return null;
	return new Date(ms + BEIJING_OFFSET_MS).toISOString().slice(0, 10);
}

export function endOfBeijingDay(date) {
	const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
	if (!match) return Number.NaN;
	const year = Number(match[1]);
	const month = Number(match[2]);
	const day = Number(match[3]);
	return Date.UTC(year, month - 1, day, 23, 59, 59, 999) - BEIJING_OFFSET_MS;
}

export function assemble(orders, events, options = {}) {
	const { date } = options;
	if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
		throw new Error("date 必须是 YYYY-MM-DD");
	}
	const includeFee = Object.prototype.hasOwnProperty.call(options, "feeBps");
	const feeBps = includeFee ? options.feeBps : 0;
	if (includeFee && (!Number.isInteger(feeBps) || feeBps < 0)) {
		throw new Error("feeBps 必须是非负整数");
	}
	const cutoff = endOfBeijingDay(date);
	if (Number.isNaN(cutoff)) {
		throw new Error("无法计算截止时间");
	}

	const ordersById = new Map();
	for (const order of orders) {
		if (!ordersById.has(order.id)) ordersById.set(order.id, order);
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const paymentByOrder = new Map();
	const refundByOrder = new Map();
	const feeByOrder = new Map();
	const audit = {
		duplicates: [],
		notSucceeded: [],
		afterCutoff: [],
		outsideOrderDate: [],
		manualReview: [],
		booked: [],
		feeBps: includeFee ? feeBps : null,
		excludedOrders: orders
			.filter((order) => beijingDate(order.createdAt) !== date)
			.map((order) => ({ id: order.id, createdAt: order.createdAt, beijingDate: beijingDate(order.createdAt) })),
	};

	const groups = [];
	const groupIndex = new Map();
	events.forEach((event, index) => {
		const key = event.eventId === undefined || event.eventId === null ? `\0missing:${index}` : String(event.eventId);
		let group = groupIndex.get(key);
		if (!group) {
			group = { eventId: event.eventId, events: [] };
			groupIndex.set(key, group);
			groups.push(group);
		}
		group.events.push(event);
	});

	for (const group of groups) {
		const signatures = new Set(group.events.map(eventSignature));
		if (group.events.length > 1 && signatures.size > 1) {
			const issue = { eventId: group.eventId, orderId: group.events[0].orderId, code: "conflicting_duplicate" };
			issues.push(issue);
			audit.manualReview.push({
				...issue,
				amount: null,
				versions: group.events.map((event) => ({
					orderId: event.orderId,
					amount: event.amount,
					kind: event.kind,
					state: event.state,
					occurredAt: event.occurredAt,
				})),
			});
			continue;
		}
		if (group.events.length > 1) {
			ignored.duplicates += group.events.length - 1;
			for (const extra of group.events.slice(1)) {
				audit.duplicates.push({ eventId: extra.eventId, orderId: extra.orderId });
			}
		}

		const event = group.events[0];
		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			audit.notSucceeded.push({ eventId: event.eventId, orderId: event.orderId, state: event.state ?? "" });
			continue;
		}

		const occurredMs = Date.parse(event.occurredAt);
		if (Number.isNaN(occurredMs) || occurredMs > cutoff) {
			ignored.afterCutoff += 1;
			audit.afterCutoff.push({ eventId: event.eventId, orderId: event.orderId, occurredAt: event.occurredAt });
			continue;
		}

		const order = ordersById.get(event.orderId);
		if (!order) {
			addIssue(event, "orphan_event");
			continue;
		}
		if (beijingDate(order.createdAt) !== date) {
			ignored.outsideOrderDate += 1;
			audit.outsideOrderDate.push({ eventId: event.eventId, orderId: event.orderId });
			continue;
		}

		const cents = readEventCents(event.amount);
		if (cents === null) {
			addIssue(event, "invalid_amount");
			continue;
		}

		if (event.kind === "payment") {
			const fee = includeFee ? feeCentsFor(cents, feeBps) : 0;
			paymentByOrder.set(event.orderId, (paymentByOrder.get(event.orderId) ?? 0) + cents);
			if (includeFee) feeByOrder.set(event.orderId, (feeByOrder.get(event.orderId) ?? 0) + fee);
			audit.booked.push({ eventId: event.eventId, orderId: event.orderId, kind: event.kind, amount: event.amount, feeCents: fee });
		} else if (event.kind === "refund") {
			refundByOrder.set(event.orderId, (refundByOrder.get(event.orderId) ?? 0) + cents);
			audit.booked.push({ eventId: event.eventId, orderId: event.orderId, kind: event.kind, amount: event.amount, feeCents: 0 });
		}
	}

	const rows = orders
		.filter((order) => beijingDate(order.createdAt) === date)
		.map((order) => {
			if (!isValidAmount(order.amount)) {
				throw new Error(`订单 ${order.id} 金额不合法`);
			}
			const amountCents = toCents(order.amount);
			const paymentCents = paymentByOrder.get(order.id) ?? 0;
			const refundCents = refundByOrder.get(order.id) ?? 0;
			const netCents = paymentCents - refundCents;
			const row = {
				id: order.id,
				amountCents,
				paymentCents,
				refundCents,
				netCents,
				outstandingCents: Math.max(amountCents - paymentCents, 0),
				overpaidCents: Math.max(paymentCents - amountCents, 0),
				status: statusFor(amountCents, paymentCents, refundCents),
			};
			if (includeFee) {
				row.feeCents = feeByOrder.get(order.id) ?? 0;
				row.settlementCents = netCents - row.feeCents;
			}
			return row;
		})
		.sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));

	const totals = {
		orderCount: rows.length,
		orderCents: 0,
		paymentCents: 0,
		refundCents: 0,
		netCents: 0,
		outstandingCents: 0,
		overpaidCents: 0,
	};
	if (includeFee) {
		totals.feeCents = 0;
		totals.settlementCents = 0;
	}
	for (const row of rows) {
		totals.orderCents += row.amountCents;
		totals.paymentCents += row.paymentCents;
		totals.refundCents += row.refundCents;
		totals.netCents += row.netCents;
		totals.outstandingCents += row.outstandingCents;
		totals.overpaidCents += row.overpaidCents;
		if (includeFee) {
			totals.feeCents += row.feeCents;
			totals.settlementCents += row.settlementCents;
		}
	}

	return {
		report: { date, timezone: "Asia/Shanghai", totals, orders: rows, ignored, issues },
		audit,
	};

	function addIssue(event, code) {
		const issue = { eventId: event.eventId, orderId: event.orderId, code };
		issues.push(issue);
		audit.manualReview.push({ ...issue, amount: event.amount ?? null });
	}
}

export function reconcile(orders, events, options) {
	return assemble(orders, events, options).report;
}

function eventSignature(event) {
	return JSON.stringify([event.orderId ?? null, event.amount ?? null, event.kind ?? null, event.state ?? null, event.occurredAt ?? null]);
}

function readEventCents(value) {
	if (!isValidAmount(value)) return null;
	try {
		return toCents(value);
	} catch {
		return null;
	}
}

function statusFor(amountCents, paymentCents, refundCents) {
	if (refundCents > 0) return "refunded";
	if (paymentCents === 0) return "unpaid";
	if (paymentCents < amountCents) return "partial";
	if (paymentCents > amountCents) return "overpaid";
	return "paid";
}

import { formatMoney } from "./money.mjs";

export function renderCsv(report) {
	const includeFee = Object.prototype.hasOwnProperty.call(report.totals, "feeCents");
	const header = ["order_id", "amount", "payment", "refund", "net", "status", "outstanding", "overpaid"];
	if (includeFee) header.push("fee", "settlement");
	const lines = [header.join(",")];
	for (const row of report.orders) {
		const cells = [
			row.id,
			formatMoney(row.amountCents),
			formatMoney(row.paymentCents),
			formatMoney(row.refundCents),
			formatMoney(row.netCents),
			row.status,
			formatMoney(row.outstandingCents),
			formatMoney(row.overpaidCents),
		];
		if (includeFee) cells.push(formatMoney(row.feeCents), formatMoney(row.settlementCents));
		lines.push(cells.join(","));
	}
	return `${lines.join("\n")}\n`;
}

export function renderSummary(report, audit = {}) {
	const { totals } = report;
	const yuan = (cents) => `${formatMoney(cents)} 元`;
	const lines = [
		`# ${report.date} 日结交接（北京时间）`,
		"",
		`时区：Asia/Shanghai（UTC+08:00）。本表只列入北京时间 ${report.date} 创建的订单，并只计入截至当天 23:59:59.999 已经发生的成功支付和成功退款。补单按 occurredAt 归属，不按收到文件的时间。`,
		"",
		"## 合计",
		"",
		`- 订单笔数：${totals.orderCount}`,
		`- 订单金额：${yuan(totals.orderCents)}（${totals.orderCents} 分）`,
		`- 收款：${yuan(totals.paymentCents)}（${totals.paymentCents} 分）`,
		`- 退款：${yuan(totals.refundCents)}（${totals.refundCents} 分）`,
		`- 净收款：${yuan(totals.netCents)}（${totals.netCents} 分）`,
		`- 未收齐：${yuan(totals.outstandingCents)}（${totals.outstandingCents} 分）`,
		`- 多付款：${yuan(totals.overpaidCents)}（${totals.overpaidCents} 分）`,
		"",
		`本日成功收款 ${yuan(totals.paymentCents)}，成功退款 ${yuan(totals.refundCents)}，净收款 ${yuan(totals.netCents)}。`,
		"",
	];

	if (Object.prototype.hasOwnProperty.call(totals, "feeCents")) {
		const bps = audit.feeBps ?? 0;
		const rateText = bps === 60 ? "0.6%（万分之 60）" : `万分之 ${bps}`;
		lines.push(`渠道手续费率为 ${rateText}，只对已入账的成功支付逐笔四舍五入到分后再汇总，合计 ${yuan(totals.feeCents)}。预计到账 ${yuan(totals.settlementCents)}，等于净收款减手续费。净收款仍是收款减退款，没有把手续费静默扣进净收款。退款不新收手续费，也不退还原手续费。`, "");
	}

	const outstanding = report.orders.filter((order) => order.outstandingCents > 0);
	const overpaid = report.orders.filter((order) => order.overpaidCents > 0);
	const refunded = report.orders.filter((order) => order.refundCents > 0);
	const settled = report.orders.filter((order) => order.outstandingCents === 0 && order.overpaidCents === 0 && order.refundCents === 0);

	lines.push("## 需要催款的订单（未收齐，不是退款）", "");
	lines.push("未收齐只表示原订单金额还没有被成功支付收齐。退款不会被再记成一笔欠款，也不能用退款去冲未收齐。");
	lines.push("");
	if (outstanding.length === 0) {
		lines.push("没有需要催款的订单。", "");
	} else {
		for (const order of outstanding) {
			lines.push(`- ${order.id}：订单 ${yuan(order.amountCents)}，已成功支付 ${yuan(order.paymentCents)}，未收齐 ${yuan(order.outstandingCents)}，成功退款 ${yuan(order.refundCents)}，状态 ${order.status}。请按未收齐金额跟进，不要把它当成退款。`);
		}
		lines.push("");
	}

	lines.push("## 需要处理多付款的订单", "");
	if (overpaid.length === 0) {
		lines.push("没有多付款订单。", "");
	} else {
		for (const order of overpaid) {
			lines.push(`- ${order.id}：订单 ${yuan(order.amountCents)}，已成功支付 ${yuan(order.paymentCents)}，多付 ${yuan(order.overpaidCents)}，成功退款 ${yuan(order.refundCents)}，状态 ${order.status}。失败或等待中的退款没有用来冲减多付款。`);
		}
		lines.push("");
	}

	lines.push("## 已经退款的订单（与未收齐分开）", "");
	if (refunded.length === 0) {
		lines.push("没有已经发生成功退款的订单。", "");
	} else {
		for (const order of refunded) {
			const feeText = Object.prototype.hasOwnProperty.call(order, "feeCents") ? `，手续费 ${yuan(order.feeCents)}，预计到账 ${yuan(order.settlementCents)}` : "";
			lines.push(`- ${order.id}：订单 ${yuan(order.amountCents)}，成功支付 ${yuan(order.paymentCents)}，成功退款 ${yuan(order.refundCents)}，净收 ${yuan(order.netCents)}${feeText}，未收齐 ${yuan(order.outstandingCents)}，多付 ${yuan(order.overpaidCents)}，状态 ${order.status}。这是已经退款，不是未收齐。`);
		}
		lines.push("");
	}

	lines.push("## 已收齐且没有退款、没有多付的订单", "");
	if (settled.length === 0) {
		lines.push("没有此类订单。", "");
	} else {
		for (const order of settled) {
			const feeText = Object.prototype.hasOwnProperty.call(order, "feeCents") ? `，手续费 ${yuan(order.feeCents)}，预计到账 ${yuan(order.settlementCents)}` : "";
			lines.push(`- ${order.id}：${yuan(order.amountCents)}，状态 ${order.status}${feeText}。`);
		}
		lines.push("");
	}

	const booked = audit.booked ?? [];
	lines.push("## 需要人工核查的通知", "");
	lines.push("下列通知没有计入收款、退款、净收款、手续费或预计到账。不要把它们伪装成订单。");
	lines.push("");
	if (report.issues.length === 0) {
		lines.push("没有需要人工核查的通知。", "");
	} else {
		for (const issue of report.issues) {
			const detail = (audit.manualReview ?? []).find((item) => item.eventId === issue.eventId && item.code === issue.code);
			if (issue.code === "orphan_event") {
				lines.push(`- 通知 ${issue.eventId}，订单号 ${issue.orderId}，原因 orphan_event：找不到订单。金额 ${detail?.amount ?? "未知"} 未计入总额。`);
			} else if (issue.code === "invalid_amount") {
				lines.push(`- 通知 ${issue.eventId}，订单号 ${issue.orderId}，原因 invalid_amount：金额 ${detail?.amount ?? "未知"} 不合法，未计入总额。`);
			} else if (issue.code === "conflicting_duplicate") {
				const versions = detail?.versions ?? [];
				const versionText = versions.length
					? `现有版本：${versions.map((version) => `${version.kind} ${version.amount}，状态 ${version.state}，发生时间 ${version.occurredAt}`).join("；")}。`
					: "";
				lines.push(`- 通知 ${issue.eventId}，订单号 ${issue.orderId}，原因 conflicting_duplicate：这组通知有矛盾，需要核对渠道账单。${versionText}脚本不能决定哪一个版本是真的，整组都没有入账，也没有默认采用第一条。`);
				const related = booked.filter((item) => item.orderId === issue.orderId && item.eventId !== issue.eventId);
				if (related.length > 0) {
					lines.push(`- 订单 ${issue.orderId} 的 ${related.map((item) => item.eventId).join("、")} 是独立通知，不属于 ${issue.eventId} 冲突组，已按 occurredAt 单独入账。`);
				}
			} else {
				lines.push(`- 通知 ${issue.eventId}，订单号 ${issue.orderId}，原因 ${issue.code}。`);
			}
		}
		lines.push("");
	}

	const duplicateIds = uniqueIds(audit.duplicates);
	const failedIds = (audit.notSucceeded ?? []).map((item) => `${item.eventId}（${item.state || "未知状态"}）`);
	const lateIds = uniqueIds(audit.afterCutoff);
	const otherDateIds = uniqueIds(audit.outsideOrderDate);
	lines.push("## 已忽略、未入账的通知", "");
	lines.push(`- 完全重复：${report.ignored.duplicates} 条${formatIds(duplicateIds)}。同一 eventId 且订单、金额、类型、状态、发生时间完全一致的通知只入账一次。receivedAt 不参与比较。`);
	lines.push(`- 失败或等待中：${report.ignored.notSucceeded} 条${formatIds(failedIds)}。`);
	lines.push(`- 晚于当天 23:59:59.999：${report.ignored.afterCutoff} 条${formatIds(lateIds)}。`);
	lines.push(`- 属于其他日期的订单：${report.ignored.outsideOrderDate} 条${formatIds(otherDateIds)}。这些不是找不到订单。`);
	if (booked.length > 0) {
		lines.push(`- 已入账通知：${booked.map((item) => item.eventId).join("、")}。`);
	}
	lines.push("");

	const excluded = audit.excludedOrders ?? [];
	lines.push("## 已经执行的检查", "");
	lines.push(`- 已按北京时间核对订单创建时间。本日列入 ${totals.orderCount} 笔；不属于本日的订单有 ${excluded.length} 笔${excluded.length ? `（${excluded.map((order) => `${order.id} 的北京日期是 ${order.beijingDate ?? "无法识别"}`).join("、")}）` : ""}。`);
	lines.push("- 已按通知 occurredAt 截到当天 23:59:59.999（含），没有用 receivedAt 或收到文件的时间代替发生时间。等于截止时刻的通知计入，更晚的不计入。");
	lines.push("- 已按顺序处理通知：先隔离同一 eventId 的矛盾版本，再去掉完全重复，再排除失败或等待中，再排除晚于截止，然后区分找不到订单、其他日期订单和非法金额。");
	lines.push("- 已确认矛盾版本、重复、失败、等待中、晚于截止、其他日期、找不到订单、金额不合法的通知都没有进入收款、退款、手续费或预计到账。");
	lines.push("- 金额全部按整数分计算。负数、空字符串、科学计数法、NaN、超过两位小数都视为非法金额，没有用小数直接乘 100。");
	lines.push("- 已把未收齐和退款分开：未收齐只看订单金额减成功支付；有成功退款的订单单独列出。订单状态只是报表分类，没有自动催款或自动退款。");
	if (Object.prototype.hasOwnProperty.call(totals, "feeCents")) {
		lines.push("- 手续费只对最终入账的成功支付逐笔四舍五入到分后相加；退款没有减手续费。预计到账等于净收款减手续费。");
	}
	lines.push("- 输出订单已按订单号排序。CSV 金额是两位小数的元，JSON 金额是整数分。");
	lines.push("");

	lines.push("## 剩余限制", "");
	lines.push("- 只根据本次读入的订单和通知计算，没有联网，也没有核对支付渠道原始账单，也没有改动真实业务系统。");
	lines.push("- 晚于截止时间的成功通知留到后续日期，本表不预估、不提前入账。");
	lines.push("- 同一 eventId 如果出现互相矛盾的版本，只能整组交给人工核对渠道账单，脚本不能指定哪一版为真。在核对前，相关订单的收齐状态不包含这组金额。");
	if (Object.prototype.hasOwnProperty.call(totals, "feeCents")) {
		lines.push("- 手续费只按已入账成功支付逐笔四舍五入到分；退款不退手续费。费率来自本次参数，没有另行询价。");
	} else {
		lines.push("- 本次没有传入手续费费率，按零费率处理，净收款等于收款减退款，没有扣渠道手续费。");
	}
	lines.push("- 找不到订单或不合法的金额不会自动补成订单，也不会悄悄并进总额。");
	lines.push("");
	return `${lines.join("\n")}\n`;
}

function uniqueIds(items = []) {
	return [...new Set(items.map((item) => item.eventId).filter(Boolean))];
}

function formatIds(ids) {
	return ids.length ? `：${ids.join("、")}` : "";
}

{
  "name": "shop-daily-reconciliation",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test/*.test.mjs",
