		],
		[
			{ eventId: "dup", orderId: "A", kind: "payment", state: "succeeded", amount: "80.00", occurredAt: "2026-10-20T01:00:00Z" },
			{ eventId: "dup", orderId: "A", kind: "payment", state: "succeeded", amount: "80.00", occurredAt: "2026-10-20T01:00:00Z", receivedAt: "2026-10-21T00:00:00Z" },
			{ eventId: "dup", orderId: "A", kind: "payment", state: "succeeded", amount: "80.00", occurredAt: "2026-10-20T01:00:00Z" },
