			{ eventId: "orphan-bad", orderId: "GHOST", kind: "payment", state: "succeeded", amount: "-1.00", occurredAt: "2026-10-20T04:00:00Z" },
			{ eventId: "other-bad", orderId: "YESTERDAY", kind: "payment", state: "succeeded", amount: "1e2", occurredAt: "2026-10-20T04:00:00Z" },
			{ eventId: "other-ok", orderId: "TOMORROW", kind: "payment", state: "succeeded", amount: "9.00", occurredAt: "2026-10-20T05:00:00Z" },
			{ eventId: "edge", orderId: "B", kind: "payment", state: "succeeded", amount: "40.00", occurredAt: "2026-10-20T15:59:59.999Z" },
