test("illegal conflicting version is not booked and not reclassified", () => {
	const report = reconcile(
		[{ id: "O", amount: "10.00", createdAt: "2026-10-20T01:00:00Z" }],
		[
			{ eventId: "c", orderId: "O", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T02:00:00Z" },
			{ eventId: "c", orderId: "O", kind: "payment", state: "succeeded", amount: "-1.00", occurredAt: "2026-10-20T02:00:00Z" },
		],
