		],
		{ date: day },
	);
	assert.equal(report.orders[0].paymentCents, 300);
	assert.equal(report.ignored.duplicates, 0);
	assert.equal(report.ignored.notSucceeded, 0);
	assert.equal(report.ignored.afterCutoff, 0);
	assert.deepEqual(report.issues, [{ eventId: "c1", orderId: "O", code: "conflicting_duplicate" }]);
});

test("refund does not create outstanding and overpayment stays visible", () => {
	const report = reconcile(
		[{ id: "R", amount: "50.00", createdAt: "2026-10-20T01:00:00Z" }],
		[
			{ eventId: "p", orderId: "R", kind: "payment", state: "succeeded", amount: "80.00", occurredAt: "2026-10-20T02:00:00Z" },
			{ eventId: "r", orderId: "R", kind: "refund", state: "succeeded", amount: "90.00", occurredAt: "2026-10-20T03:00:00Z" },
		],
