	assert.equal(report.orders[0].netCents, -1000);
	assert.equal(report.totals.netCents, -1000);
});

test("small payments sum exactly and zero fee still adds settlement columns", () => {
	const report = reconcile(
		[{ id: "S", amount: "0.30", createdAt: "2026-10-20T01:00:00Z" }],
		[
			{ eventId: "a", orderId: "S", kind: "payment", state: "succeeded", amount: "0.10", occurredAt: "2026-10-20T02:00:00Z" },
			{ eventId: "b", orderId: "S", kind: "payment", state: "succeeded", amount: "0.20", occurredAt: "2026-10-20T03:00:00Z" },
			{ eventId: "c", orderId: "S", kind: "refund", state: "succeeded", amount: "0.00", occurredAt: "2026-10-20T04:00:00Z" },
		],
		{ date: day, feeBps: 60 },
	);
	assert.equal(report.orders[0].paymentCents, 30);
	assert.equal(report.orders[0].status, "paid");
	assert.equal(report.orders[0].feeCents, 0);
	assert.equal(report.orders[0].settlementCents, 30);
	assert.equal(report.totals.feeCents, 0);
	assert.match(renderCsv(report), /fee,settlement/);
});

