import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import { renderCsv, renderSummary } from "../src/format.mjs";
import { feeCentsFor, formatMoney, isValidAmount, toCents } from "../src/money.mjs";
import { assemble, beijingDate, endOfBeijingDay, reconcile } from "../src/reconcile.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const day = "2026-10-20";

test("one simple payment", () => {
	const report = reconcile(
		[{ id: "demo", amount: "10.00", createdAt: "2026-10-20T01:00:00Z" }],
		[{ eventId: "demo-pay", orderId: "demo", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T02:00:00Z" }],
		{ date: day },
	);
	assert.equal(report.totals.netCents, 1000);
	assert.equal(report.orders[0].status, "paid");
	assert.equal(report.timezone, "Asia/Shanghai");
	assert.equal(Object.hasOwn(report.totals, "feeCents"), false);
});

test("amount parsing stays exact to the cent", () => {
	assert.equal(toCents("0.29"), 29);
	assert.equal(toCents("1.15"), 115);
	assert.equal(toCents("199.90"), 19990);
	assert.equal(toCents("0.10"), 10);
	assert.equal(toCents("0.20"), 20);
	assert.equal(toCents("0.30"), 30);
	assert.equal(toCents("80"), 8000);
	assert.equal(toCents("0.5"), 50);
	assert.equal(toCents("00.10"), 10);
	assert.equal(formatMoney(19990), "199.90");
	assert.equal(formatMoney(-500), "-5.00");
	assert.equal(formatMoney(0), "0.00");
	for (const value of ["", "NaN", "nan", "1e2", "1E2", "1.5e1", "-5.00", "-0.00", "1.234", "10.000", "+10.00", " 10.00", "10.00 ", ".5", "10.", "Infinity", null, undefined, 10.1, Number.NaN]) {
		assert.equal(isValidAmount(value), false, String(value));
	}
});

test("fee is rounded half up per booked payment", () => {
	assert.equal(feeCentsFor(50, 100), 1);
	assert.equal(feeCentsFor(150, 100), 2);
	assert.equal(feeCentsFor(100, 60), 1);
	assert.equal(feeCentsFor(50, 60), 0);
	assert.equal(feeCentsFor(19990, 60), 120);
	assert.equal(feeCentsFor(3000, 60), 18);
	assert.equal(feeCentsFor(10000, 60), 60);
});

test("beijing day boundaries and inclusive cutoff", () => {
	assert.equal(beijingDate("2026-10-19T16:00:00.000Z"), day);
	assert.equal(beijingDate("2026-10-19T15:59:59.999Z"), "2026-10-19");
	assert.equal(beijingDate("2026-10-20T15:59:59.999Z"), day);
	assert.equal(beijingDate("2026-10-20T16:00:00.000Z"), "2026-10-21");
	assert.equal(beijingDate("2026-10-20T00:00:00+08:00"), day);
	assert.equal(endOfBeijingDay(day), Date.parse("2026-10-20T15:59:59.999Z"));
});

test("filters use the documented order and keep refunds out of outstanding", () => {
	const report = reconcile(
		[
			{ id: "B", amount: "100.00", createdAt: "2026-10-20T02:00:00Z" },
