			{ eventId: "pending", orderId: "B", kind: "refund", state: "pending", amount: "1.00", occurredAt: "2026-10-20T03:00:00Z" },
			{ eventId: "late-missing", orderId: "NOPE", kind: "payment", state: "succeeded", amount: "8.00", occurredAt: "2026-10-20T16:00:00Z" },
