function formatIssueList(issues) {
	if (issues.length === 0) {
		return "无";
	}

	return issues.map((issue) => `- ${issue.eventId} (${issue.orderId}) -> ${issue.code}`).join("\n");
}

function buildSummary(report) {
	const dueOrders = report.orders.filter((order) => order.outstandingCents > 0);
	const overpaidOrders = report.orders.filter((order) => order.overpaidCents > 0);
	const refundedOrders = report.orders.filter((order) => order.refundCents > 0);

	const lines = [
		`# ${report.date} 日结说明`,
		"",
		`- 收款：${formatMoney(report.totals.paymentCents)} 元`,
		`- 退款：${formatMoney(report.totals.refundCents)} 元`,
		`- 净收款：${formatMoney(report.totals.netCents)} 元`,
		"",
		"## 需要处理的订单",
		`- 待催款：${dueOrders.length > 0 ? dueOrders.map((order) => `${order.id} ${formatMoney(order.outstandingCents)}元`).join("；") : "无"}`,
		`- 需要处理多付款：${overpaidOrders.length > 0 ? overpaidOrders.map((order) => `${order.id} ${formatMoney(order.overpaidCents)}元`).join("；") : "无"}`,
		`- 已退款：${refundedOrders.length > 0 ? refundedOrders.map((order) => `${order.id} ${formatMoney(order.refundCents)}元`).join("；") : "无"}`,
		"",
		"## 人工核查",
		`- 需人工核查：${formatIssueList(report.issues)}`,
		"",
		"## 已执行检查",
		"- 按北京时间过滤创建日期与通知发生日期；只统计当天创建订单；通知按 `occurredAt` 计算，并在当天 23:59:59.999 结束前计入。",
		"- 仅统计 `state: \"succeeded\"` 且 `kind` 为 `payment` / `refund` 的有效通知；重复 `eventId` 只计一次。",
		"- 过滤失败、等待中的通知、找到不到订单的孤儿事件、非当天订单、金额不合法的通知；这些都不计入财务合计。",
		"- 订单状态按退款、未付、部分付款、多付款、全额付款分类，并保持金额精确到分。",
		"",
		"## 剩余限制",
		"- 本次按 README 第一轮需求处理，未纳入 `data/events-update.json` 与第二轮冲突去重/手续费扩展规则。",
	];

	return `${lines.join("\n")}\n`;
}

const args = process.argv.slice(2);
const options = Object.fromEntries(Array.from({ length: args.length / 2 }, (_, index) => [args[index * 2].slice(2), args[index * 2 + 1]]));
const orders = JSON.parse(readFileSync(options.orders, "utf8"));
const events = JSON.parse(readFileSync(options.events, "utf8"));
const report = reconcile(orders, events, { date: options.date });
mkdirSync(options.out, { recursive: true });
writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);
const csv = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
for (const row of report.orders) {
	csv.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents)].join(","));
}
writeFileSync(join(options.out, `${options.date}.csv`), `${csv.join("\n")}\n`);
writeFileSync(join(options.out, "summary.md"), buildSummary(report));
console.log(JSON.stringify({ json: `${options.out}/${options.date}.json`, csv: `${options.out}/${options.date}.csv`, summary: `${options.out}/summary.md` }));

