}

function buildSummary(report) {
	const dueOrders = report.orders.filter((order) => order.outstandingCents > 0);
	const overpaidOrders = report.orders.filter((order) => order.overpaidCents > 0);
	const refundedOrders = report.orders.filter((order) => order.refundCents > 0);

