}

function normalizeEventSignature(event) {
	return [event.eventId, event.orderId, event.kind, event.state, event.amount, event.occurredAt].join("|");
}

export function reconcile(orders, events, { date }) {
	const orderMap = new Map(orders.map((order) => [order.id, order]));
	const dailyOrders = orders
		.filter((order) => toShanghaiDate(order.createdAt) === date)
		.sort((left, right) => left.id.localeCompare(right.id));

	const rowsById = new Map(
		dailyOrders.map((order) => {
			const amountCents = toCents(order.amount);
			return [
				order.id,
				{
					id: order.id,
					amountCents,
					paymentCents: 0,
					refundCents: 0,
					netCents: 0,
					outstandingCents: 0,
					overpaidCents: 0,
					status: "unpaid",
				},
			];
		}),
	);

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seenEventIds = new Map();

	for (const event of events) {
		const signature = normalizeEventSignature(event);
		if (seenEventIds.has(event.eventId) && seenEventIds.get(event.eventId) === signature) {
			ignored.duplicates += 1;
			continue;
		}

		seenEventIds.set(event.eventId, signature);

		if (event.state !== "succeeded" || !["payment", "refund"].includes(event.kind)) {
			ignored.notSucceeded += 1;
			continue;
		}

		if (toShanghaiDate(event.occurredAt) !== date) {
			ignored.afterCutoff += 1;
			continue;
		}

		const order = orderMap.get(event.orderId);
		if (!order) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}

		if (toShanghaiDate(order.createdAt) !== date) {
			ignored.outsideOrderDate += 1;
			continue;
		}

		if (!isValidMoneyString(event.amount)) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}

		const amountCents = toCents(event.amount);
		const row = rowsById.get(event.orderId);
		if (!row) {
			continue;
		}

		if (event.kind === "payment") {
			row.paymentCents += amountCents;
		} else {
			row.refundCents += amountCents;
		}
	}

	const rows = Array.from(rowsById.values()).sort((left, right) => left.id.localeCompare(right.id));
	for (const row of rows) {
		row.netCents = row.paymentCents - row.refundCents;
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);

		if (row.refundCents > 0) {
			row.status = "refunded";
		} else if (row.paymentCents === 0) {
			row.status = "unpaid";
		} else if (row.paymentCents < row.amountCents) {
			row.status = "partial";
		} else if (row.paymentCents > row.amountCents) {
			row.status = "overpaid";
		} else {
			row.status = "paid";
		}
	}

	const totals = {
		orderCount: rows.length,
		orderCents: rows.reduce((sum, row) => sum + row.amountCents, 0),
		paymentCents: rows.reduce((sum, row) => sum + row.paymentCents, 0),
		refundCents: rows.reduce((sum, row) => sum + row.refundCents, 0),
		netCents: rows.reduce((sum, row) => sum + row.netCents, 0),
		outstandingCents: rows.reduce((sum, row) => sum + row.outstandingCents, 0),
		overpaidCents: rows.reduce((sum, row) => sum + row.overpaidCents, 0),
	};

	return {
		date,
		timezone: "Asia/Shanghai",
		totals,
		orders: rows,
		ignored,
		issues,
	};
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { formatMoney } from "./money.mjs";
import { reconcile } from "./reconcile.mjs";

function formatIssueList(issues) {
	if (issues.length === 0) {
		return "无";
	}

	return issues.map((issue) => `- ${issue.eventId} (${issue.orderId}) -> ${issue.code}`).join("\n");
}

function buildSummary(report) {
	const dueOrders = report.orders.filter((order) => order.outstandingCents > 0);
	const overpaidOrders = report.orders.filter((order) => order.overpaidCents > 0);
	const refundedOrders = report.orders.filter((order) => order.refundCents > 0);

	const lines = [
		`# ${report.date} 日结说明`,
		"",
		`- 收款：${formatMoney(report.totals.paymentCents)} 元`,
		`- 退款：${formatMoney(report.totals.refundCents)} 元`,
		`- 净收款：${formatMoney(report.totals.netCents)} 元`,
		"",
		"## 需要处理的订单",
		`- 待催款：${dueOrders.length > 0 ? dueOrders.map((order) => `${order.id} ${formatMoney(order.outstandingCents)}元`).join("；") : "无"}`,
		`- 需要处理多付款：${overpaidOrders.length > 0 ? overpaidOrders.map((order) => `${order.id} ${formatMoney(order.overpaidCents)}元`).join("；") : "无"}`,
		`- 已退款：${refundedOrders.length > 0 ? refundedOrders.map((order) => `${order.id} ${formatMoney(order.refundCents)}元`).join("；") : "无"}`,
		"",
		"## 人工核查",
		`- 需人工核查：${formatIssueList(report.issues)}`,
		"",
		"## 已执行检查",
		"- 按北京时间过滤创建日期与通知发生日期；只统计当天创建订单；通知按 `occurredAt` 计算，并在当天 23:59:59.999 结束前计入。",
		"- 仅统计 `state: \"succeeded\"` 且 `kind` 为 `payment` / `refund` 的有效通知；重复 `eventId` 只计一次。",
		"- 过滤失败、等待中的通知、找到不到订单的孤儿事件、非当天订单、金额不合法的通知；这些都不计入财务合计。",
		"- 订单状态按退款、未付、部分付款、多付款、全额付款分类，并保持金额精确到分。",
		"",
		"## 剩余限制",
		"- 本次按 README 第一轮需求处理，未纳入 `data/events-update.json` 与第二轮冲突去重/手续费扩展规则。",
	];

	return `${lines.join("\n")}\n`;
}

const args = process.argv.slice(2);
const options = Object.fromEntries(Array.from({ length: args.length / 2 }, (_, index) => [args[index * 2].slice(2), args[index * 2 + 1]]));
const orders = JSON.parse(readFileSync(options.orders, "utf8"));
const events = JSON.parse(readFileSync(options.events, "utf8"));
const report = reconcile(orders, events, { date: options.date });
mkdirSync(options.out, { recursive: true });
writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);
const csv = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
for (const row of report.orders) {
	csv.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents)].join(","));
}
writeFileSync(join(options.out, `${options.date}.csv`), `${csv.join("\n")}\n`);
writeFileSync(join(options.out, "summary.md"), buildSummary(report));
console.log(JSON.stringify({ json: `${options.out}/${options.date}.json`, csv: `${options.out}/${options.date}.csv`, summary: `${options.out}/summary.md` }));

