import { isValidMoneyString, toCents } from "./money.mjs";

function toShanghaiDate(value) {
	if (!value) {
		return "";
	}

	const date = new Date(value);
	if (Number.isNaN(date.getTime())) {
		return "";
	}

	const parts = new Intl.DateTimeFormat("en-CA", {
		timeZone: "Asia/Shanghai",
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).formatToParts(date);

	const map = Object.fromEntries(parts.filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
	return `${map.year}-${map.month}-${map.day}`;
}

function normalizeEventSignature(event) {
	return [event.eventId, event.orderId, event.kind, event.state, event.amount, event.occurredAt].join("|");
}

export function reconcile(orders, events, { date }) {
	const orderMap = new Map(orders.map((order) => [order.id, order]));
	const dailyOrders = orders
		.filter((order) => toShanghaiDate(order.createdAt) === date)
		.sort((left, right) => left.id.localeCompare(right.id));

	const rowsById = new Map(
		dailyOrders.map((order) => {
			const amountCents = toCents(order.amount);
			return [
				order.id,
				{
					id: order.id,
					amountCents,
					paymentCents: 0,
					refundCents: 0,
					netCents: 0,
					outstandingCents: 0,
					overpaidCents: 0,
					status: "unpaid",
				},
			];
		}),
	);

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seenEventIds = new Map();

	for (const event of events) {
		const signature = normalizeEventSignature(event);
		if (seenEventIds.has(event.eventId) && seenEventIds.get(event.eventId) === signature) {
			ignored.duplicates += 1;
			continue;
		}

		seenEventIds.set(event.eventId, signature);

		if (event.state !== "succeeded" || !["payment", "refund"].includes(event.kind)) {
			ignored.notSucceeded += 1;
			continue;
		}

		if (toShanghaiDate(event.occurredAt) !== date) {
			ignored.afterCutoff += 1;
			continue;
		}

		const order = orderMap.get(event.orderId);
		if (!order) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}

		if (toShanghaiDate(order.createdAt) !== date) {
			ignored.outsideOrderDate += 1;
			continue;
		}

		if (!isValidMoneyString(event.amount)) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}

		const amountCents = toCents(event.amount);
		const row = rowsById.get(event.orderId);
		if (!row) {
			continue;
		}

		if (event.kind === "payment") {
			row.paymentCents += amountCents;
		} else {
			row.refundCents += amountCents;
		}
	}

	const rows = Array.from(rowsById.values()).sort((left, right) => left.id.localeCompare(right.id));
	for (const row of rows) {
		row.netCents = row.paymentCents - row.refundCents;
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);

		if (row.refundCents > 0) {
			row.status = "refunded";
		} else if (row.paymentCents === 0) {
			row.status = "unpaid";
		} else if (row.paymentCents < row.amountCents) {
			row.status = "partial";
		} else if (row.paymentCents > row.amountCents) {
			row.status = "overpaid";
		} else {
			row.status = "paid";
		}
	}

	const totals = {
		orderCount: rows.length,
		orderCents: rows.reduce((sum, row) => sum + row.amountCents, 0),
		paymentCents: rows.reduce((sum, row) => sum + row.paymentCents, 0),
		refundCents: rows.reduce((sum, row) => sum + row.refundCents, 0),
