import { toCents } from "./money.mjs";

const SHANGHAI_OFFSET_MS = 8 * 60 * 60 * 1000;

export function shanghaiBounds(date) {
	const start = Date.parse(`${date}T00:00:00.000+08:00`);
	if (Number.isNaN(start)) throw new Error(`invalid date: ${date}`);
	return { start, end: start + 24 * 60 * 60 * 1000 - 1 };
}

function eventSignature(event) {
	return JSON.stringify([event.orderId, event.amount, event.kind, event.state, event.occurredAt]);
}

function statusOf(row) {
	if (row.refundCents > 0) return "refunded";
	if (row.paymentCents === 0) return "unpaid";
	if (row.paymentCents < row.amountCents) return "partial";
	if (row.paymentCents > row.amountCents) return "overpaid";
	return "paid";
}

export function reconcile(orders, events, { date, feeBps = 0 } = {}) {
	const { start, end } = shanghaiBounds(date);
	const orderById = new Map(orders.map((order) => [order.id, order]));
	const inDay = new Map();
	for (const order of orders) {
		const created = Date.parse(order.createdAt);
		if (created >= start && created <= end) inDay.set(order.id, order);
	}

	const rows = new Map();
	for (const order of [...inDay.values()].sort((left, right) => left.id.localeCompare(right.id))) {
		const amountCents = toCents(order.amount);
		if (amountCents === null) throw new Error(`invalid order amount: ${order.id}`);
		rows.set(order.id, {
			id: order.id,
			amountCents,
			paymentCents: 0,
			refundCents: 0,
			feeCents: 0,
			netCents: 0,
			settlementCents: 0,
			outstandingCents: amountCents,
			overpaidCents: 0,
			status: "unpaid",
		});
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seen = new Map();
	const conflicting = new Set();

	for (const event of events) {
		const signature = eventSignature(event);
		const previous = seen.get(event.eventId);
		if (previous === undefined) {
			seen.set(event.eventId, signature);
			continue;
		}
		if (previous !== signature) conflicting.add(event.eventId);
	}

	const applied = new Set();
	for (const event of events) {
		if (conflicting.has(event.eventId)) {
			if (!applied.has(`conflict:${event.eventId}`)) {
				applied.add(`conflict:${event.eventId}`);
				issues.push({ eventId: event.eventId, orderId: event.orderId, code: "conflicting_duplicate" });
			}
			continue;
		}
		if (applied.has(event.eventId)) {
			ignored.duplicates += 1;
			continue;
		}
		applied.add(event.eventId);
		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			continue;
		}
		const occurred = Date.parse(event.occurredAt);
		if (Number.isNaN(occurred) || occurred > end) {
			ignored.afterCutoff += 1;
			continue;
		}
		if (!orderById.has(event.orderId)) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}
		if (!inDay.has(event.orderId)) {
			ignored.outsideOrderDate += 1;
			continue;
		}
		const amountCents = toCents(event.amount);
		if (amountCents === null) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}
		const row = rows.get(event.orderId);
		if (event.kind === "payment") {
			row.paymentCents += amountCents;
			if (feeBps) row.feeCents += Math.round((amountCents * feeBps) / 10000);
		} else if (event.kind === "refund") {
			row.refundCents += amountCents;
		}
	}

	const reportOrders = [...rows.values()].map((row) => {
		row.netCents = row.paymentCents - row.refundCents;
		row.settlementCents = row.netCents - row.feeCents;
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
		row.status = statusOf(row);
		return row;
	});

	const totals = {
		orderCount: reportOrders.length,
		orderCents: 0,
		paymentCents: 0,
		refundCents: 0,
		netCents: 0,
		outstandingCents: 0,
		overpaidCents: 0,
		feeCents: 0,
		settlementCents: 0,
	};
	for (const row of reportOrders) {
		totals.orderCents += row.amountCents;
		totals.paymentCents += row.paymentCents;
		totals.refundCents += row.refundCents;
		totals.netCents += row.netCents;
		totals.outstandingCents += row.outstandingCents;
		totals.overpaidCents += row.overpaidCents;
		totals.feeCents += row.feeCents;
		totals.settlementCents += row.settlementCents;
	}

	const report = {
		date,
		timezone: "Asia/Shanghai",
		totals,
		orders: reportOrders,
		ignored,
		issues,
	};
	if (!feeBps) {
		delete totals.feeCents;
		delete totals.settlementCents;
		for (const row of reportOrders) {
			delete row.feeCents;
			delete row.settlementCents;
		}
	}
	return report;
}

export function renderSummary(report) {
	const yuan = (cents) => `${(cents / 100).toFixed(2)} 元（${cents} 分）`;
	const chase = report.orders.filter((order) => order.outstandingCents > 0);
	const overpaid = report.orders.filter((order) => order.overpaidCents > 0);
	const refunded = report.orders.filter((order) => order.status === "refunded");
	const lines = [
		`# ${report.date} 日结说明`,
		"",
		`统计时区：北京时间（${report.timezone}）。只包含当天创建的订单，支付和退款计到当天 23:59:59.999 为止。`,
		"",
		"## 合计",
		"",
		`- 订单 ${report.totals.orderCount} 笔，订单金额 ${yuan(report.totals.orderCents)}`,
		`- 收款 ${yuan(report.totals.paymentCents)}`,
		`- 退款 ${yuan(report.totals.refundCents)}`,
		`- 净收款 ${yuan(report.totals.netCents)}`,
		`- 未收齐 ${yuan(report.totals.outstandingCents)}`,
		`- 多付款 ${yuan(report.totals.overpaidCents)}`,
	];
	if (report.totals.feeCents !== undefined) {
		lines.push(`- 手续费 ${yuan(report.totals.feeCents)}`, `- 结算金额 ${yuan(report.totals.settlementCents)}`);
	}
	lines.push("", "## 需要催款的订单", "");
	if (chase.length === 0) lines.push("- 无");
	for (const order of chase) {
		lines.push(`- ${order.id}：状态 ${order.status}，未收齐 ${yuan(order.outstandingCents)}，已收 ${yuan(order.paymentCents)}，应收 ${yuan(order.amountCents)}`);
	}
	lines.push("", "## 需要处理多付款的订单", "");
	if (overpaid.length === 0) lines.push("- 无");
	for (const order of overpaid) {
		lines.push(`- ${order.id}：多付 ${yuan(order.overpaidCents)}，已收 ${yuan(order.paymentCents)}，应收 ${yuan(order.amountCents)}`);
	}
	lines.push("", "## 已退款订单（不等于未收齐）", "");
	if (refunded.length === 0) lines.push("- 无");
	for (const order of refunded) {
		lines.push(`- ${order.id}：退款 ${yuan(order.refundCents)}，净收 ${yuan(order.netCents)}，未收齐 ${yuan(order.outstandingCents)}`);
	}
	lines.push("", "## 人工核查", "");
	if (report.issues.length === 0) lines.push("- 无");
	for (const issue of report.issues) {
		const meaning = issue.code === "orphan_event" ? "找不到订单" : issue.code === "invalid_amount" ? "金额不合法" : "同一通知编号存在互相矛盾的版本，需要核对渠道账单，脚本不能决定哪个版本为真";
		lines.push(`- ${issue.eventId} / 订单 ${issue.orderId}：${meaning}（${issue.code}），未计入总额`);
	}
	lines.push(
		"",
		"## 已执行的检查",
		"",
		"- 订单创建时间和通知发生时间都按北京时间判断，跨日边界单独核对。",
		"- 金额先校验为非负、最多两位小数的十进制字符串，再换算成整数分，避免浮点误差。",
		"- 完全相同的通知编号只入账一次；失败和等待中的通知不入账。",
		"- 晚于当天 23:59:59.999 的通知暂不计入；不属于当天的订单通知不记为孤儿，也不进入合计。",
		"- 找不到订单、金额不合法，以及互相矛盾的重复通知单独列出，不计入收款、退款和净收款。",
		"- 未收齐只按订单金额减去成功支付计算，退款单独列示，不会再记成欠款。",
		"",
		"## 剩余限制",
		"",
		"- 报表只分类，不会自动发催款或退款。",
		"- 等待中、失败和截止后的通知留待后续日结，不在本次补记。",
		"- 手续费只在显式传入费率时计算；未传费率时不扣手续费，净收款仍是收款减退款。",
		"- 矛盾通知只提示人工核对渠道账单，不替财务选择版本。",
		"",
	);
	return lines.join("\n");
}

